"use client";

import React, { forwardRef } from "react";
import { motion, AnimatePresence, HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

/**
 * The main Dynamic Island wrapper.
 * Automatically resizes based on its children using Framer Motion layout animations.
 */
export interface DynamicIslandProps extends HTMLMotionProps<"div"> {
  children: React.ReactNode;
  /** Custom spring configuration for the layout morph */
  spring?: { stiffness: number; damping: number; mass?: number };
}

export const DynamicIsland = forwardRef<HTMLDivElement, DynamicIslandProps>(
  ({ children, spring = { stiffness: 400, damping: 30 }, className, ...props }, ref) => {
    return (
      <motion.div
        ref={ref}
        layout
        transition={{
          type: "spring",
          stiffness: spring.stiffness,
          damping: spring.damping,
          mass: spring.mass,
        }}
        className={cn(
          "bg-black text-white rounded-[2rem] overflow-hidden shadow-2xl relative",
          className
        )}
        {...props}
      >
        {children}
      </motion.div>
    );
  }
);
DynamicIsland.displayName = "DynamicIsland";

/**
 * A wrapper for content inside the Dynamic Island.
 * Handles the enter/exit fading when states change.
 */
export interface DynamicIslandContentProps {
  children: React.ReactNode;
  /** Unique key to trigger AnimatePresence transitions */
  id: string;
  className?: string;
}

export function DynamicIslandContent({ children, id, className }: DynamicIslandContentProps) {
  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={id}
        initial={{ opacity: 0, scale: 0.9, filter: "blur(4px)" }}
        animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
        exit={{ opacity: 0, scale: 0.9, filter: "blur(4px)", position: "absolute" }}
        transition={{ duration: 0.2 }}
        className={cn("w-full h-full flex flex-col justify-center", className)}
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}

"use client";

import React, { useState } from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

export interface Tab {
  id: string;
  label: string;
}

export interface GlassTabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  tabs: Tab[];
  activeTab?: string;
  onChange?: (id: string) => void;
  /** Optional custom ID for layout animations if using multiple instances on the same page */
  layoutId?: string;
}

export function GlassTabs({
  tabs,
  activeTab: controlledActiveTab,
  onChange,
  layoutId = "glass-tab-indicator",
  className,
  ...props
}: GlassTabsProps) {
  const [internalTab, setInternalTab] = useState(tabs[0]?.id);
  const activeTab = controlledActiveTab !== undefined ? controlledActiveTab : internalTab;
  const containerRef = React.useRef<HTMLDivElement>(null);

  const handleTabChange = (id: string) => {
    if (controlledActiveTab === undefined) {
      setInternalTab(id);
    }
    onChange?.(id);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const currentIndex = tabs.findIndex((t) => t.id === activeTab);
    if (currentIndex === -1) return;

    let nextIndex = currentIndex;
    if (e.key === "ArrowRight") {
      nextIndex = (currentIndex + 1) % tabs.length;
    } else if (e.key === "ArrowLeft") {
      nextIndex = (currentIndex - 1 + tabs.length) % tabs.length;
    } else {
      return;
    }

    e.preventDefault();
    const nextTab = tabs[nextIndex];
    handleTabChange(nextTab.id);

    // Set focus to the new tab button
    const buttons = containerRef.current?.querySelectorAll("button");
    if (buttons && buttons[nextIndex]) {
      buttons[nextIndex].focus();
    }
  };

  return (
    <div
      ref={containerRef}
      role="tablist"
      aria-orientation="horizontal"
      onKeyDown={handleKeyDown}
      className={cn(
        "relative flex items-center p-1.5 bg-white/5 backdrop-blur-xl border border-white/10 rounded-full shadow-[0_4px_24px_-8px_rgba(0,0,0,0.5)]",
        className
      )}
      {...props}
    >
      {tabs.map((tab) => {
        const isActive = activeTab === tab.id;

        return (
          <button
            key={tab.id}
            role="tab"
            aria-selected={isActive}
            tabIndex={isActive ? 0 : -1}
            onClick={() => handleTabChange(tab.id)}
            className={cn(
              "relative px-5 py-2 text-sm font-medium transition-colors duration-300 outline-none focus-visible:ring-2 focus-visible:ring-indigo-500/50 focus-visible:ring-offset-2 focus-visible:ring-offset-black rounded-full",
              isActive ? "text-white" : "text-zinc-400 hover:text-zinc-200"
            )}
            style={{
              // Prevent tap highlight on mobile
              WebkitTapHighlightColor: "transparent",
            }}
          >
            {isActive && (
              <motion.div
                layoutId={layoutId}
                className="absolute inset-0 z-0 bg-white/10 border border-white/20 rounded-full shadow-[inset_0_1px_1px_rgba(255,255,255,0.2)]"
                transition={{
                  type: "spring",
                  stiffness: 400,
                  damping: 30,
                  mass: 0.8,
                }}
                style={{
                  // The backdrop-blur is actually what creates the physical glass distortion 
                  // as it slides over the background colors.
                  backdropFilter: "blur(12px)",
                  WebkitBackdropFilter: "blur(12px)",
                }}
              />
            )}
            <span className="relative z-10">{tab.label}</span>
          </button>
        );
      })}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { motion, useScroll, useMotionValueEvent, HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

export interface SmartNavbarProps extends Omit<HTMLMotionProps<"nav">, "children"> {
  children: React.ReactNode;
  threshold?: number;
  glass?: boolean;
  container?: React.RefObject<HTMLElement>;
}

export function SmartNavbar({
  children,
  threshold = 50,
  glass = true,
  container,
  className,
  ...props
}: SmartNavbarProps) {
  const { scrollY } = useScroll({ container });
  const [hidden, setHidden] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useMotionValueEvent(scrollY, "change", (latest) => {
    const previous = scrollY.getPrevious() ?? 0;
    
    if (latest > threshold) {
      setIsScrolled(true);
    } else {
      setIsScrolled(false);
    }

    // Only update hidden state if we've actually scrolled a decent amount
    // or if we're near the top
    if (latest <= threshold) {
      setHidden(false);
    } else if (latest > previous + 5) {
      // Scrolling down
      setHidden(true);
    } else if (latest < previous - 5) {
      // Scrolling up
      setHidden(false);
    }
  });

  return (
    <motion.nav
      variants={{
        visible: { y: 0 },
        hidden: { y: "-100%" },
      }}
      animate={hidden ? "hidden" : "visible"}
      transition={{ duration: 0.35, ease: "easeInOut" }}
      className={cn(
        "fixed top-0 left-0 right-0 z-50 flex items-center justify-between transition-colors duration-300",
        isScrolled && glass
          ? "bg-background/70 backdrop-blur-md border-b border-border/50"
          : "bg-transparent border-transparent",
        !glass && isScrolled ? "bg-background border-b border-border/50" : "",
        className
      )}
      {...props}
    >
      {children}
    </motion.nav>
  );
}

