"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Loader2, Check, ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";

export type ButtonState = "idle" | "loading" | "success";

export interface MorphingStateButtonProps {
  onClick?: () => Promise<void>;
  idleText?: string;
  className?: string;
}

export function MorphingStateButton({
  onClick,
  idleText = "Submit",
  className,
}: MorphingStateButtonProps) {
  const [buttonState, setButtonState] = useState<ButtonState>("idle");

  const handleClick = async () => {
    if (buttonState !== "idle") return;
    
    setButtonState("loading");
    
    if (onClick) {
      try {
        await onClick();
        setButtonState("success");
      } catch (e) {
        setButtonState("idle");
      }
    } else {
      // Simulate network request
      setTimeout(() => setButtonState("success"), 2000);
    }

    // Reset after success
    setTimeout(() => {
      setButtonState((current) => (current === "success" ? "idle" : current));
    }, 4000);
  };

  return (
    <motion.button
      layout
      onClick={handleClick}
      className={cn(
        "relative flex items-center justify-center overflow-hidden font-medium text-white shadow-lg outline-none",
        buttonState === "idle" ? "bg-zinc-900 hover:bg-zinc-800 rounded-full px-8 py-3 h-12 w-40" : "",
        buttonState === "loading" ? "bg-zinc-800 rounded-full h-12 w-12" : "",
        buttonState === "success" ? "bg-emerald-500 rounded-full h-12 w-12 shadow-[0_0_40px_rgba(16,185,129,0.5)]" : "",
        className
      )}
      transition={{ type: "spring", stiffness: 300, damping: 20 }}
      whileTap={buttonState === "idle" ? { scale: 0.95 } : undefined}
    >
      <AnimatePresence mode="wait">
        {buttonState === "idle" && (
          <motion.div
            key="idle"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="flex items-center gap-2 whitespace-nowrap"
          >
            <span>{idleText}</span>
            <ArrowRight className="w-4 h-4" />
          </motion.div>
        )}

        {buttonState === "loading" && (
          <motion.div
            key="loading"
            initial={{ opacity: 0, scale: 0.5 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.5 }}
          >
            <Loader2 className="w-5 h-5 animate-spin text-zinc-400" />
          </motion.div>
        )}

        {buttonState === "success" && (
          <motion.div
            key="success"
            initial={{ opacity: 0, scale: 0.5, rotate: -45 }}
            animate={{ opacity: 1, scale: 1, rotate: 0 }}
            exit={{ opacity: 0, scale: 0.5 }}
            transition={{ type: "spring", stiffness: 400, damping: 15, delay: 0.1 }}
          >
            <Check className="w-6 h-6 text-white stroke-[3]" />
          </motion.div>
        )}
      </AnimatePresence>
    </motion.button>
  );
}

"use client";

import React, { useRef } from "react";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";

export type TiltVariant = "standard" | "reverse" | "push";

interface TiltCardProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  /** Max tilt rotation in degrees. Default: 15 */
  tiltIntensity?: number;
  /** Animation speed multiplier. Default: 1 */
  speed?: number;
  /** Initial scale modifier. Default: 1 */
  scale?: number;
  /** Base hover color. */
  color?: string;
  /** The interaction variant. Default: "standard" */
  variant?: TiltVariant;
}

export function TiltCard({
  children,
  className,
  tiltIntensity = 15,
  speed = 1,
  scale = 1,
  color,
  variant = "standard",
  ...props
}: TiltCardProps) {
  const ref = useRef<HTMLDivElement>(null);

  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const activeStiffness = 150 * speed;
  const activeDamping = 20 / speed;

  const mouseXSpring = useSpring(x, { stiffness: activeStiffness, damping: activeDamping });
  const mouseYSpring = useSpring(y, { stiffness: activeStiffness, damping: activeDamping });

  const activeIntensity = tiltIntensity * scale;
  const invert = variant === "reverse" ? -1 : 1;

  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], [activeIntensity * invert, -activeIntensity * invert]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], [-activeIntensity * invert, activeIntensity * invert]);
  const translateZ = useTransform(mouseXSpring, () => {
    if (variant === "push") {
      // Calculate distance from center to push down
      const distance = Math.sqrt(x.get() ** 2 + y.get() ** 2);
      return distance * -50; 
    }
    return 0;
  });

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const xPct = mouseX / width - 0.5;
    const yPct = mouseY / height - 0.5;

    x.set(xPct);
    y.set(yPct);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  const [hovered, setHovered] = React.useState(false);

  return (
    <motion.div
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => {
        handleMouseLeave();
        setHovered(false);
      }}
      style={{
        rotateX,
        rotateY,
        z: translateZ,
        transformStyle: "preserve-3d",
        borderColor: hovered && color ? color : undefined,
        boxShadow: hovered && color ? `0 0 20px ${color}15` : undefined,
        ...props.style,
      }}
      className={cn(
        "relative rounded-2xl border border-border bg-card p-8 shadow-sm transition-colors duration-300",
        className
      )}
      {...(props as any)}
    >
      <div style={{ transform: "translateZ(50px)" }} className="relative z-10 h-full w-full">
        {children}
      </div>

      {/* Gloss effect */}
      <motion.div
        className="pointer-events-none absolute inset-0 rounded-2xl opacity-0 transition-opacity duration-300 group-hover:opacity-100"
        style={{
          background: color
            ? `linear-gradient(135deg, ${color}20 0%, ${color}00 50%)`
            : "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 50%)",
          transform: "translateZ(1px)",
        }}
      />
    </motion.div>
  );
}

"use client";

import React, { useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { motion, useAnimationFrame } from "framer-motion";

export type SpotlightVariant = "soft" | "strong" | "ring" | "pulse";

interface SpotlightCardProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  /** The color of the spotlight. Default: "rgba(99, 102, 241, 0.15)" */
  spotlightColor?: string;
  /** An alias for spotlightColor */
  color?: string;
  /** Size multiplier for the spotlight. Default: 1 */
  scale?: number;
  /** Visual variant of the spotlight. Default: "soft" */
  variant?: SpotlightVariant;
}

export function SpotlightCard({
  children,
  className,
  spotlightColor = "rgba(99, 102, 241, 0.15)",
  color,
  scale = 1,
  variant = "soft",
  ...props
}: SpotlightCardProps) {
  const divRef = useRef<HTMLDivElement>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [opacity, setOpacity] = useState(0);

  // For the pulse variant
  const timeRef = useRef(0);
  const [pulseRadius, setPulseRadius] = useState(0);

  useAnimationFrame((t, delta) => {
    if (variant === "pulse" && opacity > 0) {
      timeRef.current += delta;
      // Oscillate between 0.8 and 1.2
      const sine = Math.sin(timeRef.current / 400);
      setPulseRadius(sine * 0.2 + 1);
    }
  });

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!divRef.current || isFocused) return;
    const rect = divRef.current.getBoundingClientRect();
    setPosition({ x: e.clientX - rect.left, y: e.clientY - rect.top });
  };

  const handleFocus = () => {
    setIsFocused(true);
    setOpacity(1);
  };

  const handleBlur = () => {
    setIsFocused(false);
    setOpacity(0);
  };

  const handleMouseEnter = () => setOpacity(1);
  const handleMouseLeave = () => setOpacity(0);

  const activeColor = color
    ? color.startsWith("#")
      ? `${color}25`
      : color
    : spotlightColor;

  const baseRadius = scale * 600;
  const currentRadius = variant === "pulse" ? baseRadius * pulseRadius : baseRadius;

  let gradientString = "";
  switch (variant) {
    case "strong":
      gradientString = `radial-gradient(${currentRadius * 0.7}px circle at ${position.x}px ${position.y}px, ${activeColor}, transparent 70%)`;
      break;
    case "ring":
      gradientString = `radial-gradient(${currentRadius}px circle at ${position.x}px ${position.y}px, transparent 20%, ${activeColor} 40%, transparent 60%)`;
      break;
    case "soft":
    case "pulse":
    default:
      gradientString = `radial-gradient(${currentRadius}px circle at ${position.x}px ${position.y}px, ${activeColor}, transparent 40%)`;
      break;
  }

  return (
    <div
      ref={divRef}
      onMouseMove={handleMouseMove}
      onFocus={handleFocus}
      onBlur={handleBlur}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      className={cn(
        "relative overflow-hidden rounded-2xl border border-border/50 bg-background/50 shadow-sm transition-colors hover:border-border",
        className
      )}
      {...props}
    >
      <div
        className="pointer-events-none absolute -inset-px opacity-0 transition-opacity duration-300"
        style={{
          opacity,
          background: gradientString,
        }}
      />
      {children}
    </div>
  );
}

"use client";

import React from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

export type BentoVariant = "standard" | "glow" | "scale";

interface BentoGridProps {
  children: React.ReactNode;
  className?: string;
  speed?: number;
  scale?: number;
  color?: string;
  variant?: BentoVariant;
}

export function BentoGrid({
  children,
  className,
  speed = 1,
  scale = 1,
  color,
  variant = "standard",
}: BentoGridProps) {
  // Pass playground props down to children
  const childrenWithProps = React.Children.map(children, (child) => {
    if (React.isValidElement(child)) {
      return React.cloneElement(child, { speed, scale, color, variant } as any);
    }
    return child;
  });

  return (
    <div className="@container w-full">
      <motion.div
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-50px" }}
        variants={{
          visible: {
            transition: { staggerChildren: 0.1 / speed },
          },
        }}
        className={cn("grid grid-cols-1 @md:grid-cols-3 gap-4 max-w-7xl mx-auto w-full", className)}
      >
        {childrenWithProps}
      </motion.div>
    </div>
  );
}

interface BentoCardProps {
  className?: string;
  title?: string | React.ReactNode;
  description?: string | React.ReactNode;
  icon?: React.ReactNode;
  header?: React.ReactNode;
  children?: React.ReactNode;
  speed?: number;
  scale?: number;
  color?: string;
  variant?: BentoVariant;
}

export function BentoCard({
  className,
  title,
  description,
  icon,
  header,
  children,
  speed = 1,
  scale = 1,
  color,
  variant = "standard",
}: BentoCardProps) {
  const [hovered, setHovered] = React.useState(false);

  const hoverVariants = {
    standard: { y: -5 * scale },
    glow: { y: 0, boxShadow: color ? `0 0 25px ${color}30` : "0 0 25px rgba(255,255,255,0.1)" },
    scale: { y: 0, scale: 1.02 * scale },
  };

  return (
    <motion.div
      variants={{
        hidden: { opacity: 0, y: 20, filter: "blur(10px)" },
        visible: {
          opacity: 1,
          y: 0,
          filter: "blur(0px)",
          transition: { duration: 0.7 / speed, ease: [0.16, 1, 0.3, 1] },
        },
      }}
      whileHover={hoverVariants[variant]}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      className={cn(
        "relative rounded-3xl group/bento p-6 flex flex-col space-y-4 overflow-hidden border border-border/50 bg-background/50 backdrop-blur-xl shadow-sm transition-all duration-300 hover:border-border",
        className
      )}
      style={{
        borderColor: hovered && color && variant !== "glow" ? color : undefined,
      }}
    >
      {/* Subtle hover gradient background */}
      <div
        className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-purple-500/5 opacity-0 group-hover/bento:opacity-100 transition-opacity duration-500 pointer-events-none"
        style={{
          background:
            hovered && color
              ? `linear-gradient(135deg, ${color}10 0%, ${color}00 70%)`
              : undefined,
        }}
      />

      {header && (
        <div className="flex-1 w-full min-h-[8rem] rounded-2xl overflow-hidden bg-muted/50 border border-border/50 relative">
          {header}
        </div>
      )}

      <div className="group-hover/bento:translate-x-1 transition-transform duration-300 z-10 flex flex-col h-full justify-end">
        {icon && <div className="mb-3 text-zinc-400">{icon}</div>}
        {title && (
          <h3 className="font-semibold text-lg text-foreground tracking-tight mb-2">
            {title}
          </h3>
        )}
        {description && (
          <div className="font-light text-muted-foreground text-sm leading-relaxed">
            {description}
          </div>
        )}
      </div>
      {children}
    </motion.div>
  );
}

