            <div className="grid grid-cols-2 gap-4 border-t border-white/10 pt-4 mt-2">
              <div>
                <p className="text-zinc-500 font-mono text-[10px] tracking-widest mb-1">DATE</p>
                <p className="font-medium text-sm text-zinc-300">{date}</p>
              </div>
              <div>
                <p className="text-zinc-500 font-mono text-[10px] tracking-widest mb-1">TYPE</p>
                <p className="font-medium text-sm text-amber-400">{type}</p>
              </div>
            </div>
          </div>

          <div className="h-[150px] pt-12 flex flex-col items-center justify-end">
             {/* Fake Barcode */}
             <div className="w-full h-12 flex gap-1 bg-white p-2 rounded items-center opacity-80 mix-blend-screen">
                {Array.from({ length: 40 }).map((_, i) => (
                  <div key={i} className="bg-black h-full" style={{ width: `${(Math.sin(i * 137) * 0.5 + 0.5) * 4 + 1}px` }} />
                ))}
             </div>
             <p className="mt-2 text-[10px] font-mono tracking-[0.3em] text-zinc-500">
               {ticketNumber.replace('#', '')} {Math.abs(ticketNumber.split('').reduce((a, b) => a + b.charCodeAt(0), 0) * 1234 % 10000).toString().padStart(4, '0')}
             </p>
          </div>
        </div>

        {/* Holographic Foil Layer */}
        <motion.div
          className="absolute inset-0 z-20 pointer-events-none mix-blend-color-dodge opacity-60"
          style={{
            backgroundImage: useTransform(
              [glareX, glareY],
              ([x, y]) => `radial-gradient(circle at ${x}% ${y}%, rgba(255,100,200,0.8) 0%, rgba(100,200,255,0.4) 30%, rgba(255,255,100,0.2) 60%, transparent 80%)`
            )
          }}
        />
        
        {/* Specular Highlight */}
        <motion.div
          className="absolute inset-0 z-30 pointer-events-none mix-blend-overlay opacity-50"
          style={{
            backgroundImage: useTransform(
              [glareX, glareY],
              ([x, y]) => `radial-gradient(circle at ${x}% ${y}%, rgba(255,255,255,0.8) 0%, transparent 50%)`
            )
          }}
        />

        {/* Grain overlay for texture */}
        <div 
          className="absolute inset-0 z-40 opacity-20 mix-blend-overlay pointer-events-none"
          style={{ backgroundImage: "url('https://grainy-gradients.vercel.app/noise.svg')" }}
        />
      </motion.div>
    </div>
  );
}

"use client";

import React, { useRef, useState } from "react";
import { motion, useMotionValue, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";

export interface ThreeDCardPeelProps {
  frontImage: string;
  backImage: string;
  className?: string;
}

export function ThreeDCardPeel({ frontImage, backImage, className }: ThreeDCardPeelProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isHovered, setIsHovered] = useState(false);

  // We track the mouse position from the top right corner
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    // Distance from top right corner
    const x = rect.right - e.clientX;
    const y = e.clientY - rect.top;
    
    // Only peel if we are somewhat near the top right
    mouseX.set(Math.max(0, Math.min(x, rect.width)));
    mouseY.set(Math.max(0, Math.min(y, rect.height)));
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    // Animate back to 0
    mouseX.set(0);
    mouseY.set(0);
  };

  // The clip path for the front card to hide the peeling corner
  const frontClipPath = useTransform([mouseX, mouseY], ([x, y]: any) => {
    // If x and y are 0, no peel
    if (!isHovered) return "polygon(0 0, 100% 0, 100% 100%, 0 100%)";
    
    // Calculate the cut points on the top and right edges
    const cutRight = Math.max(0, 100 - (y / 3)); // percentage
    const cutTop = Math.max(0, 100 - (x / 3)); // percentage
    
    // It creates a triangle cut at the top right
    return `polygon(0 0, ${cutTop}% 0, 100% ${100 - cutRight}%, 100% 100%, 0 100%)`;
  });

  // The peeled flap is a bit tricky to do purely in CSS with dynamic mouse.
  // Instead, we will do a simpler but highly effective 3D fold on hover using Framer Motion 3D transforms.
  
  // Let's pivot to a highly polished 3D fold/peel effect that guarantees 60fps
  return (
    <div
      ref={containerRef}
      className={cn("relative w-64 h-96 cursor-pointer group perspective-[1200px]", className)}
    >
      <motion.div
        className="w-full h-full relative preserve-3d transition-transform duration-500 ease-out group-hover:rotate-y-[-15deg] group-hover:rotate-x-[5deg]"
      >
        {/* Back Content (What's underneath the peel) */}
        <div 
          className="absolute inset-0 rounded-2xl bg-cover bg-center overflow-hidden shadow-2xl"
          style={{ backgroundImage: `url(${backImage})` }}
        >
          {/* Internal shadow to make it look like a recess */}
          <div className="absolute inset-0 bg-black/40 shadow-[inset_0_0_40px_rgba(0,0,0,0.8)]" />
        </div>

        {/* Front Content (The sticker that peels away) */}
        <motion.div
          className="absolute inset-0 rounded-2xl bg-cover bg-center shadow-lg origin-top-right transition-all duration-500 ease-out z-10"
          style={{ backgroundImage: `url(${frontImage})` }}
          whileHover={{ 
            rotateX: -25, 
            rotateY: 25, 
            x: -15, 
            y: 15,
            scale: 0.95
          }}
        >
          {/* Glossy shine overlay */}
          <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/10 to-white/40 opacity-0 group-hover:opacity-100 transition-opacity duration-500 rounded-2xl" />
        </motion.div>
      </motion.div>
    </div>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

export type GlyphTheme = "matrix" | "cyber" | "binary" | "runic";

interface GlyphMatrixProps extends React.HTMLAttributes<HTMLDivElement> {
  theme?: GlyphTheme;
  fontSize?: number;
  speed?: number;
  density?: number; // spacing multiplier, e.g. 1.2
  fadeSpeed?: number; // trail length: 0.04 (long trails) to 0.15 (short trails)
  interactive?: boolean;
  glow?: boolean;
}

const CHARSETS: Record<GlyphTheme, string> = {
  matrix: "ｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜﾝ1234567890:*+-<>|",
  cyber: "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#@$%&{}[];:?/",
  binary: "01",
  runic: "ᚠᚢᚦᚨᚲᚷᚹᚺᚾᛁᛃᛇᛈᛉᛊᛏᛒᛖᛗᛚᛜᛞᛟ"
};

const THEME_COLORS: Record<GlyphTheme, { primary: string; glow: string; highlight: string }> = {
  matrix: {
    primary: "rgba(16, 185, 129, 0.85)", // Emerald
    glow: "#10b981",
    highlight: "#ffffff"
  },
  cyber: {
    primary: "rgba(236, 72, 153, 0.85)", // Pink
    glow: "#ec4899",
    highlight: "#22d3ee" // Cyan
  },
  binary: {
    primary: "rgba(59, 130, 246, 0.85)", // Blue
    glow: "#3b82f6",
    highlight: "#10b981" // Emerald
  },
  runic: {
    primary: "rgba(249, 115, 22, 0.85)", // Orange
    glow: "#f97316",
    highlight: "#ffe4e6" // Rose
  }
};

export function GlyphMatrix({
  theme = "matrix",
  fontSize = 14,
  speed = 1.2,
  density = 1.1,
  fadeSpeed = 0.06,
  interactive = true,
  glow = true,
  className,
  ...props
}: GlyphMatrixProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mouseRef = useRef<{ x: number | null; y: number | null }>({ x: null, y: null });

  const activeCharset = CHARSETS[theme];
  const colors = THEME_COLORS[theme];

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationFrameId: number;
    let width = 0;
    let height = 0;
    let columns = 0;
    let drops: number[] = [];

    const resize = () => {
      if (!canvas || !containerRef.current) return;
      
      const rect = containerRef.current.getBoundingClientRect();
      width = rect.width;
      height = rect.height;

      // Adjust for high DPI displays
      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);

      // Re-calculate columns
      columns = Math.floor(width / (fontSize * density));
      
      // Preserve or fill drops array
      const oldDrops = [...drops];
      drops = new Array(columns).fill(0).map((_, i) => {
        return oldDrops[i] !== undefined ? oldDrops[i] : Math.random() * -100;
      });
    };

    resize();

    // Use ResizeObserver to make component container responsive
    const resizeObserver = new ResizeObserver(() => {
      resize();
    });
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }

    const draw = () => {
      ctx.fillStyle = `rgba(0, 0, 0, ${fadeSpeed})`;
      ctx.fillRect(0, 0, width, height);

      ctx.font = `${fontSize}px monospace`;
      ctx.textAlign = "center";

      const mx = mouseRef.current.x;
      const my = mouseRef.current.y;

      for (let i = 0; i < drops.length; i++) {
        let x = i * fontSize * density + (fontSize * density) / 2;
        let y = drops[i] * fontSize;

        // Reset if it goes off bottom randomly
        if (y > height && Math.random() > 0.975) {
          drops[i] = 0;
          y = 0;
        }

        // Draw character only when it's positive
        if (y > 0) {
          // Select character
          let char = activeCharset[Math.floor(Math.random() * activeCharset.length)];
          
          // Check mouse interaction
          const dx = mx !== null ? x - mx : Infinity;
          const dy = my !== null ? y - my : Infinity;
          const distance = Math.sqrt(dx * dx + dy * dy);
          const isNearMouse = interactive && distance < 100;

          if (isNearMouse) {
            // Interactive glowing spotlight state
            ctx.fillStyle = colors.highlight;
            if (glow) {
              ctx.shadowColor = colors.glow;
              ctx.shadowBlur = 12;
            }

            // Scramble character heavily when cursor is near
            char = activeCharset[Math.floor(Math.random() * activeCharset.length)];

            // Repulsion displacement effect
            const force = (100 - distance) / 100; // 0 to 1
            const angle = Math.atan2(dy, dx);
            x += Math.cos(angle) * force * 8;
            y += Math.sin(angle) * force * 8;
          } else {
            // Standard state
            ctx.fillStyle = colors.primary;
            ctx.shadowBlur = 0; // Turn off shadow to boost performance
          }

          ctx.fillText(char, x, y);
        }

        // Increment drop y coordinate
        drops[i] += speed * (Math.random() * 0.4 + 0.8);
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      cancelAnimationFrame(animationFrameId);
      resizeObserver.disconnect();
    };
  }, [theme, fontSize, speed, density, fadeSpeed, interactive, glow, colors, activeCharset]);

  // Track mouse coordinates relative to container
  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    mouseRef.current = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  };

  const handleMouseLeave = () => {
    mouseRef.current = { x: null, y: null };
  };

  return (
    <div
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className={cn("relative w-full h-full min-h-[300px] overflow-hidden bg-black select-none", className)}
      {...props}
    >
      <canvas
        ref={canvasRef}
        className="block w-full h-full pointer-events-none"
      />
    </div>
  );
}

"use client";

import React, { useRef } from "react";
import { motion, useInView, Variants } from "framer-motion";
import { cn } from "@/lib/utils";

export type TextRevealVariant = "slide-up" | "slide-down" | "fade" | "scale";

interface TextRevealProps {
  /** The text to reveal */
  text: string;
  className?: string;
  /** Delay before animation starts (seconds). Default: 0 */
  delay?: number;
  /** Speed multiplier. Higher is faster. Default: 1 */
  speed?: number;
  /** Animation preset. Default: "slide-up" */
  variant?: TextRevealVariant;
}

const getVariants = (variant: TextRevealVariant, speed: number): Variants => {
  const duration = 0.8 / speed;

  switch (variant) {
    case "slide-down":
      return {
        hidden: { y: "-100%", opacity: 0, rotateZ: -5 },
        visible: {
          y: "0%",
          opacity: 1,
          rotateZ: 0,
          transition: { duration, ease: [0.16, 1, 0.3, 1] },
        },
      };
    case "fade":
      return {
        hidden: { opacity: 0, y: 10 },
        visible: {
          opacity: 1,
          y: 0,
          transition: { duration, ease: "easeOut" },
        },
      };
    case "scale":
      return {
        hidden: { opacity: 0, scale: 0.8, y: 20 },
        visible: {
          opacity: 1,
          scale: 1,
          y: 0,
          transition: { duration, ease: [0.175, 0.885, 0.32, 1.275] }, // BackOut
        },
      };
    case "slide-up":
    default:
      return {
        hidden: { y: "100%", opacity: 0, rotateZ: 5 },
        visible: {
          y: "0%",
          opacity: 1,
          rotateZ: 0,
          transition: { duration, ease: [0.16, 1, 0.3, 1] }, // Custom snappy ease
        },
      };
  }
};

export function TextReveal({
  text,
  className,
  delay = 0,
  speed = 1,
  variant = "slide-up",
}: TextRevealProps) {
  const ref = useRef(null);
  // Triggers once when the text is 15% visible
  const isInView = useInView(ref, { once: true, margin: "-15% 0px" });

  const words = text.split(" ");
  const childVariants = getVariants(variant, speed);

  return (
    <div
      ref={ref}
      className={cn("flex flex-wrap gap-[0.25em] overflow-hidden", className)}
    >
      {words.map((word, i) => (
        <span key={i} className="relative overflow-hidden inline-block pb-1">
          <motion.span
            variants={childVariants}
            initial="hidden"
            animate={isInView ? "visible" : "hidden"}
            transition={{ delay: delay + i * (0.05 / speed) }}
            className="inline-block transform origin-bottom-left"
          >
            {word}
          </motion.span>
        </span>
      ))}
    </div>
  );
}

"use client";

import React from "react";
import { motion, Variants, HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

export type KineticLoaderVariant = "flip" | "bounce" | "wave" | "pulse";

interface KineticLoaderProps extends HTMLMotionProps<"div"> {
  /** Text to display while loading. Default: "LOADING..." */
  text?: string;
  size?: "sm" | "md" | "lg";
  /** Animation speed multiplier. Default: 1 */
  speed?: number;
  /** Animation variant. Default: "flip" */
  variant?: KineticLoaderVariant;
  color?: string;
}

const getVariants = (variant: KineticLoaderVariant, speed: number): { container: Variants; child: Variants } => {
  const baseDuration = 0.8 / speed;
  const staggerDelay = 0.1 / speed;

  switch (variant) {
    case "bounce":
      return {
        container: {
          hidden: {},
          visible: {
            transition: { staggerChildren: staggerDelay },
          },
        },
        child: {
          hidden: { y: "0%" },
          visible: {
            y: ["0%", "-40%", "0%"],
            transition: { 
              duration: baseDuration, 
              repeat: Infinity, 
              ease: "easeInOut" 
            },
          },
        },
      };
    case "wave":
      return {
        container: {
          hidden: {},
          visible: {
            transition: { staggerChildren: staggerDelay },
          },
        },
        child: {
          hidden: { y: "0%", rotateZ: 0 },
          visible: {
            y: ["0%", "-20%", "0%"],
            rotateZ: [0, 10, -10, 0],
            transition: { 
              duration: baseDuration * 1.5, 
              repeat: Infinity, 
              ease: "easeInOut" 
            },
          },
        },
      };
    case "pulse":
      return {
        container: {
          hidden: {},
          visible: {
            transition: { staggerChildren: staggerDelay },
          },
        },
        child: {
          hidden: { opacity: 0.2, scale: 0.8 },
          visible: {
            opacity: [0.2, 1, 0.2],
            scale: [0.8, 1.1, 0.8],
            transition: { 
              duration: baseDuration, 
              repeat: Infinity, 
              ease: "easeInOut" 
            },
          },
        },
      };
    case "flip":
    default:
      return {
        container: {
          hidden: {},
          visible: {
            transition: { staggerChildren: staggerDelay },
          },
        },
        child: {
          hidden: { rotateX: -90, opacity: 0, y: 10 },
          visible: {
            rotateX: 0,
            opacity: 1,
            y: 0,
            transition: {
              duration: baseDuration,
              repeat: Infinity,
              repeatType: "reverse",
              repeatDelay: 0.5 / speed,
              ease: "easeOut",
            },
          },
        },
      };
  }
};

export function KineticLoader({
  text = "LOADING...",
  size = "md",
  speed = 1,
  variant = "flip",
  color,
  className,
  ...props
}: KineticLoaderProps) {
  const sizeClasses = {
    sm: "text-lg",
    md: "text-3xl",
    lg: "text-6xl",
  };

  const hasColorText = className?.includes("text-");
  const { container, child } = getVariants(variant, speed);

  return (
    <motion.div
      variants={container}
      initial="hidden"
      animate="visible"
      className={cn(
        "flex items-center justify-center font-bold tracking-widest perspective-1000",
        !hasColorText && !color && "text-indigo-500",
        sizeClasses[size],
        className
      )}
      style={{
        color: color || undefined,
        ...props.style,
      }}
      {...props}
    >
      {text.split("").map((char, index) => (
        <motion.span
          key={index}
          variants={child}
          className="inline-block origin-bottom transform-style-3d mr-[0.1em]"
        >
          {char === " " ? "\u00A0" : char}
        </motion.span>
      ))}
    </motion.div>
  );
}

