export function PricingCards({
  tiers = defaultTiers,
  variant = 'grid',
  color = '#6366f1',
  speed = 1,
  scale = 1,
  className
}: PricingCardsProps) {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

