    const container = containerRef.current;
    if (container) {
      container.addEventListener('mousemove', handleMouseMove);
    }
    return () => {
      if (container) container.removeEventListener('mousemove', handleMouseMove);
    };
  }, [variant]);

  return (
    <section className={cn("@container py-12 @md:py-20 bg-background text-foreground relative border-y border-border/50 overflow-hidden w-full", className)}>
      {/* Background radial glow */}
      <div
        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[100vw] @md:w-[55vw] h-[100vw] @md:h-[55vw] rounded-full blur-[100px] @md:blur-[140px] pointer-events-none opacity-50"
        style={{
          background: color ? `radial-gradient(circle, ${color}1a 0%, transparent 70%)` : 'radial-gradient(circle, rgba(99, 102, 241, 0.05) 0%, transparent 70%)'
        }}
      />

      <div className="container mx-auto px-4 @md:px-6 mb-12 @md:mb-16 relative z-10">
        <div className="text-center max-w-2xl mx-auto">
          <span
            className="font-semibold tracking-widest text-xs uppercase block mb-3"
            style={{ color: color || '#818cf8' }}
          >
            Simple Packages
          </span>
          <h2 className="text-3xl @md:text-5xl font-bold tracking-tight mb-4 text-foreground">
            Flexible Pricing for Everyone
          </h2>
          <p className="text-muted-foreground text-sm @md:text-base font-light">
            All components are open-source. Upgrade to access premium templates, custom WebGL/3D canvases, and custom shader packs.
          </p>
        </div>
      </div>

      <div
        ref={containerRef}
        className="container mx-auto px-4 @md:px-6 grid grid-cols-1 @2xl:grid-cols-3 gap-8 @md:gap-8 max-w-5xl z-10 relative group/container"
      >
        {variant === 'spotlight' && (
          <div
            className="absolute inset-0 pointer-events-none z-[-1] hidden @md:block"
            style={{
              background: `radial-gradient(800px circle at ${mousePosition.x}px ${mousePosition.y}px, ${color}15, transparent 40%)`,
            }}
          />
        )}

        {tiers.map((tier, idx) => {
          const isHovered = hoveredIdx === idx;
          const isAnyHovered = hoveredIdx !== null;

          return (
            <motion.div
              key={idx}
              onMouseEnter={() => setHoveredIdx(idx)}
              onMouseLeave={() => setHoveredIdx(null)}
              className={cn(
                "rounded-3xl border p-6 @md:p-8 flex flex-col justify-between relative transition-all duration-300 bg-card/40",
                tier.popular ? "border-border shadow-2xl mt-4 @2xl:mt-0" : "border-border/50",
                variant === 'focus' && isAnyHovered && !isHovered ? "@md:opacity-50 @md:blur-[2px] @md:scale-[0.98]" : "opacity-100 blur-0 scale-100"
              )}
              style={{
                transform: isHovered && scale !== 1 && variant !== 'focus' ? `scale(${1 + 0.02 * scale})` : undefined,
                borderColor: isHovered && color ? color : undefined,
                boxShadow: isHovered && color ? `0 0 25px ${color}10` : undefined,
                transitionDuration: `${300 / speed}ms`
              }}
            >
              {/* Rounded inner container for background effects to prevent them from breaking out */}
              <div className="absolute inset-0 rounded-3xl overflow-hidden pointer-events-none">
                {/* Spotlight shimmer inside the card for the spotight variant */}
                {variant === 'spotlight' && (
                  <div
                    className="absolute inset-0 opacity-0 group-hover/container:opacity-100 transition-opacity duration-300 mix-blend-overlay hidden @md:block"
                    style={{
                      background: `radial-gradient(400px circle at ${mousePosition.x - (idx * (containerRef.current?.clientWidth || 1000) / 3)}px ${mousePosition.y}px, ${color}30, transparent 40%)`
                    }}
                  />
                )}
                {/* Spotlight shimmer for Pro tier default */}
                {tier.popular && (
                  <div
                    className="absolute inset-0 z-0"
                    style={{
                      background: color ? `linear-gradient(to bottom, ${color}08, transparent)` : 'linear-gradient(to bottom, rgba(99, 102, 241, 0.05), transparent)'
                    }}
                  />
                )}
              </div>

              {/* Badge for Popular Tier - Moved outside overflow hidden wrapper */}
              {tier.popular && (
                <div
                  className="absolute -top-3 left-1/2 -translate-x-1/2 text-black text-[10px] font-bold uppercase tracking-wider px-3 py-1 rounded-full shadow-lg flex items-center gap-1 z-20 whitespace-nowrap"
                  style={{
                    background: color ? color : 'linear-gradient(to right, #6366f1, #ec4899)',
                    color: color ? '#000000' : undefined
                  }}
                >
                  <Sparkles className="w-3 h-3 text-black" />
                  Most Popular
                </div>
              )}

              <div className="relative z-10">
                <span className="text-muted-foreground text-xs font-bold uppercase tracking-widest block mb-1">
                  {tier.name}
                </span>
                <div className="flex flex-wrap items-baseline gap-x-1.5 gap-y-0 mb-6">
                  <span className="text-4xl @md:text-5xl font-extrabold tracking-tight text-foreground">
                    {tier.price}
                  </span>
                  <span className="text-muted-foreground text-xs font-light whitespace-nowrap">
                    / {tier.period}
                  </span>
                </div>
                <p className="text-muted-foreground text-xs font-light leading-relaxed mb-8 border-b border-border/50 pb-6">
                  {tier.desc}
                </p>

                <ul className="space-y-4 mb-8">
                  {tier.features.map((feat, i) => (
                    <li key={i} className="flex items-start text-xs font-light text-muted-foreground gap-2.5">
                      <Check
                        className="w-4 h-4 shrink-0 mt-0.5"
                        style={{ color: color || '#10b981' }}
                      />
                      <span>{feat}</span>
                    </li>
                  ))}
                </ul>
              </div>

              <div className="mt-4 relative z-10">
                <a href={tier.name === 'Starter' ? '/docs/installation' : '/pricing'} className="block w-full">
                  <MagneticButton
                    className={`w-full h-12 rounded-xl text-xs font-semibold uppercase tracking-wider transition-all border ${tier.popular
                        ? 'bg-foreground text-background border-transparent hover:opacity-90'
                        : 'border-border/60 bg-transparent text-foreground hover:bg-muted/30'
                      }`}
                    style={{
                      borderColor: tier.popular && color ? color : undefined,
                      backgroundColor: tier.popular && color ? color : undefined,
                      color: tier.popular && color ? '#000000' : undefined
                    }}
                  >
                    {tier.cta}
                  </MagneticButton>
                </a>
              </div>
            </motion.div>
          );
        })}
      </div>
    </section>
  );
}

'use client';

import React from 'react';
import { motion, Variants } from 'framer-motion';
import { cn } from '@/lib/utils';
import { Sparkles, Layers, Zap, Shield, Cpu, Activity } from 'lucide-react';

export type FeatureSectionVariant = 'grid' | 'bento' | 'minimal';

export interface FeatureItem {
  icon: React.ReactNode;
  title: string;
  description: string;
  className?: string; // used for bento layouts (e.g., md:col-span-2)
}

interface FeatureSectionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  variant?: FeatureSectionVariant;
  title?: React.ReactNode;
  subtitle?: React.ReactNode;
  features?: FeatureItem[];
  color?: string; // Primary accent color (default: indigo)
}

const defaultFeatures: FeatureItem[] = [
  {
    icon: <Zap className="w-5 h-5 text-yellow-400" />,
    title: "Lightning Fast",
    description: "Optimized for speed and minimal bundle size. Built with performance in mind.",
    className: "@2xl:col-span-2 @2xl:row-span-1" // Bento specific
  },
  {
    icon: <Shield className="w-5 h-5 text-emerald-400" />,
    title: "Secure by Default",
    description: "Best-in-class security practices integrated directly into the core architecture.",
    className: "@2xl:col-span-1 @2xl:row-span-2"
  },
  {
    icon: <Layers className="w-5 h-5 text-indigo-400" />,
    title: "Modular Design",
    description: "Use only what you need. Everything is built independently for maximum flexibility.",
    className: "@2xl:col-span-1 @2xl:row-span-1"
  },
  {
    icon: <Cpu className="w-5 h-5 text-cyan-400" />,
    title: "Type Safe",
    description: "100% written in TypeScript with strict type checking and excellent editor autocomplete.",
    className: "@2xl:col-span-1 @2xl:row-span-1"
  },
  {
    icon: <Activity className="w-5 h-5 text-rose-400" />,
    title: "Real-time Metrics",
    description: "Monitor application performance and user engagement directly from the dashboard.",
    className: "@2xl:col-span-1 @2xl:row-span-1"
  },
];

export function FeatureSection({ 
  className,
  variant = 'grid',
  color = '#6366f1', // default indigo
  title = "Supercharge Your Workflow",
  subtitle = "Everything you need to build faster and scale further, built directly into a seamless ecosystem.",
  features = defaultFeatures,
  ...props 
}: FeatureSectionProps) {
  
  const containerVariants: Variants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.08
      }
    }
  };
  
  const itemVariants: Variants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.5, ease: "easeOut" } }
  };

  const renderGridItem = (feature: FeatureItem, idx: number) => (
    <motion.div
      key={idx}
      variants={itemVariants}
      className="group relative p-6 @md:p-8 bg-zinc-900/40 backdrop-blur-md rounded-3xl border border-white/10 hover:bg-zinc-900/60 hover:border-white/20 transition-all duration-500 overflow-hidden shadow-2xl"
    >
      <div
        className="absolute inset-0 opacity-0 group-hover:opacity-20 transition-opacity duration-700 pointer-events-none"
        style={{ background: `radial-gradient(400px circle at 100% 0%, ${color}33, transparent 70%)` }}
      />

      <div className="relative z-10 flex flex-col gap-4">
        <div 
          className="w-12 h-12 rounded-2xl bg-black/80 border border-white/10 flex items-center justify-center shadow-[0_0_15px_rgba(0,0,0,0.5)] group-hover:scale-110 group-hover:border-white/20 transition-all duration-500"
        >
          {feature.icon}
        </div>
        <div>
          <h3 className="text-lg @md:text-xl font-semibold text-white mb-2 group-hover:text-transparent bg-clip-text transition-all duration-300" style={{ backgroundImage: `linear-gradient(to right, #fff, ${color})` }}>
            {feature.title}
          </h3>
          <p className="text-zinc-400 leading-relaxed font-light text-sm @md:text-base">{feature.description}</p>
        </div>
      </div>
    </motion.div>
  );

  const renderBentoItem = (feature: FeatureItem, idx: number) => (
    <motion.div
      key={idx}
      variants={itemVariants}
      className={cn(
        "group relative p-6 @md:p-8 bg-zinc-900/40 backdrop-blur-md rounded-3xl border border-white/10 hover:border-white/20 transition-all duration-500 overflow-hidden flex flex-col justify-end shadow-2xl",
        feature.className
      )}
    >
      <div
        className="absolute inset-0 opacity-0 group-hover:opacity-20 transition-opacity duration-700 pointer-events-none"
        style={{ background: `radial-gradient(800px circle at 0% 100%, ${color}40, transparent 60%)` }}
      />

      <div className="relative z-10 flex flex-col gap-4 h-full">
        <div className="w-12 h-12 rounded-2xl bg-black/80 backdrop-blur-md border border-white/10 flex items-center justify-center shadow-[0_0_15px_rgba(0,0,0,0.5)] group-hover:scale-110 group-hover:border-white/20 transition-all duration-500">
          {feature.icon}
        </div>
        <div className="mt-auto pt-8">
          <h3 className="text-lg @md:text-xl font-semibold text-white mb-2 group-hover:text-transparent bg-clip-text transition-all duration-300" style={{ backgroundImage: `linear-gradient(to right, #fff, ${color})` }}>{feature.title}</h3>
          <p className="text-zinc-400 leading-relaxed font-light text-sm @md:text-base">{feature.description}</p>
        </div>
      </div>
    </motion.div>
  );

  const renderMinimalItem = (feature: FeatureItem, idx: number) => (
    <motion.div 
      key={idx}
      variants={itemVariants}
      className="group flex gap-6 items-start"
    >
      <div className="w-12 h-12 shrink-0 rounded-full bg-white/5 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
        {feature.icon}
      </div>
      <div>
        <h3 className="text-lg font-semibold text-white mb-2 group-hover:text-transparent bg-clip-text transition-all duration-300"
            style={{ backgroundImage: `linear-gradient(to right, #fff, ${color})` }}
        >
          {feature.title}
        </h3>
        <p className="text-zinc-400 leading-relaxed font-light">{feature.description}</p>
      </div>
    </motion.div>
  );

  return (
    <div className={cn("@container w-full py-12 @md:py-24", className)} {...props}>
      <div className="max-w-5xl mx-auto px-4 @md:px-6">
        <div className="text-center max-w-2xl mx-auto mb-12 @md:mb-16 space-y-4">
          <div className="flex justify-center mb-4">
            <div
              className="p-2 rounded-full border"
              style={{ backgroundColor: `${color}15`, borderColor: `${color}30`, color }}
            >
              <Sparkles className="w-5 h-5" />
            </div>
          </div>
          <h2 className="text-3xl @md:text-5xl font-bold tracking-tight text-white">
            {title}
          </h2>
          <p className="text-zinc-400 text-sm @md:text-lg font-light leading-relaxed">
            {subtitle}
          </p>
        </div>

        <motion.div
          className={cn(
            "grid gap-6 @md:gap-8",
            variant === 'grid' && "grid-cols-1 @xl:grid-cols-2 @3xl:grid-cols-3",
            variant === 'bento' && "grid-cols-1 @2xl:grid-cols-3 @2xl:grid-rows-2 auto-rows-min",
            variant === 'minimal' && "grid-cols-1 @xl:grid-cols-2 gap-y-8 @md:gap-y-12"
          )}
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
        >
          {features.map((feature, idx) => {
            if (variant === 'bento') return renderBentoItem(feature, idx);
            if (variant === 'minimal') return renderMinimalItem(feature, idx);
            return renderGridItem(feature, idx);
          })}
        </motion.div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

/* ─── Floating Input ─── */
export interface FloatingInputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  label: string;
}

export const FloatingInput = React.forwardRef<HTMLInputElement, FloatingInputProps>(
  ({ className, label, type = "text", ...props }, ref) => {
    const [isFocused, setIsFocused] = useState(false);
    const [hasValue, setHasValue] = useState(false);

    return (
      <div className={cn("relative flex items-center w-full rounded-xl border transition-colors duration-300 bg-black/40 backdrop-blur-md", 
        isFocused ? "border-indigo-500/50 shadow-[0_0_30px_-5px_rgba(99,102,241,0.3)]" : "border-white/10",
        className
      )}>
        <div className="relative flex-1 px-4 py-2">
          <motion.label
            className="absolute left-4 text-zinc-500 pointer-events-none origin-left"
            initial={false}
            animate={{
              y: isFocused || hasValue ? -22 : 0,
              scale: isFocused || hasValue ? 0.75 : 1,
              color: isFocused ? "#818cf8" : "#71717a",
            }}
            transition={{ duration: 0.2, ease: "easeOut" }}
          >
            {label}
          </motion.label>
          <input
            ref={ref}
            type={type}
            onFocus={(e) => {
              setIsFocused(true);
              props.onFocus?.(e);
            }}
            onBlur={(e) => {
              setIsFocused(false);
              props.onBlur?.(e);
            }}
            onChange={(e) => {
              setHasValue(e.target.value.length > 0);
              props.onChange?.(e);
            }}
            className="w-full bg-transparent outline-none text-white placeholder-transparent pt-1"
            placeholder={label}
            {...props}
          />
        </div>
      </div>
    );
  }
);
FloatingInput.displayName = "FloatingInput";

/* ─── Floating Textarea ─── */
export interface FloatingTextareaProps
  extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
  label: string;
}

export const FloatingTextarea = React.forwardRef<HTMLTextAreaElement, FloatingTextareaProps>(
  ({ className, label, ...props }, ref) => {
    const [isFocused, setIsFocused] = useState(false);
    const [hasValue, setHasValue] = useState(false);

    return (
      <div className={cn("relative flex w-full rounded-xl border transition-colors duration-300 bg-black/40 backdrop-blur-md overflow-hidden", 
        isFocused ? "border-indigo-500/50 shadow-[0_0_30px_-5px_rgba(99,102,241,0.3)]" : "border-white/10",
        className
      )}>
        <div className="relative flex-1 px-4 py-3">
          <motion.label
            className="absolute left-4 top-3 text-zinc-500 pointer-events-none origin-left"
            initial={false}
            animate={{
              y: isFocused || hasValue ? -24 : 0,
              scale: isFocused || hasValue ? 0.75 : 1,
              color: isFocused ? "#818cf8" : "#71717a",
            }}
            transition={{ duration: 0.2, ease: "easeOut" }}
          >
            {label}
          </motion.label>
          <textarea
            ref={ref}
            onFocus={(e) => {
              setIsFocused(true);
              props.onFocus?.(e);
            }}
            onBlur={(e) => {
              setIsFocused(false);
              props.onBlur?.(e);
            }}
            onChange={(e) => {
              setHasValue(e.target.value.length > 0);
              props.onChange?.(e);
            }}
            className="w-full bg-transparent outline-none text-white placeholder-transparent pt-1 resize-none min-h-[100px]"
            placeholder={label}
            {...props}
          />
        </div>
      </div>
    );
  }
);
FloatingTextarea.displayName = "FloatingTextarea";

/* ─── Floating Checkbox ─── */
export interface FloatingCheckboxProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  label: string;
}

export const FloatingCheckbox = React.forwardRef<HTMLInputElement, FloatingCheckboxProps>(
  ({ className, label, ...props }, ref) => {
    // We use local state for uncontrolled usage visual feedback, 
    // but typically these are managed by a form library.
    const [isChecked, setIsChecked] = useState(props.defaultChecked || !!props.checked);

    return (
      <label className={cn("relative flex items-center gap-3 w-full rounded-xl border transition-colors duration-300 bg-black/40 backdrop-blur-md px-4 py-3 cursor-pointer select-none", 
        isChecked ? "border-indigo-500/50 shadow-[0_0_20px_-5px_rgba(99,102,241,0.2)]" : "border-white/10 hover:bg-white/5",
        className
      )}>
        <div className={cn("relative w-5 h-5 flex items-center justify-center rounded border transition-colors duration-200",
          isChecked ? "bg-indigo-500 border-indigo-500" : "bg-black/50 border-white/20"
        )}>
          <input
            type="checkbox"
            ref={ref}
            className="sr-only"
            onChange={(e) => {
              setIsChecked(e.target.checked);
              props.onChange?.(e);
            }}
            {...props}
          />
          <motion.svg
            initial={false}
            animate={{ 
              scale: isChecked ? 1 : 0, 
              opacity: isChecked ? 1 : 0 
            }}
            transition={{ type: "spring", stiffness: 400, damping: 25 }}
            className="w-3.5 h-3.5 text-white pointer-events-none"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={3}
          >
            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
          </motion.svg>
        </div>
        <span className={cn("text-sm transition-colors duration-200", isChecked ? "text-white" : "text-zinc-400")}>
          {label}
        </span>
      </label>
    );
  }
);
FloatingCheckbox.displayName = "FloatingCheckbox";

/* ─── Floating Radio ─── */
export interface FloatingRadioProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  label: string;
}

export const FloatingRadio = React.forwardRef<HTMLInputElement, FloatingRadioProps>(
  ({ className, label, ...props }, ref) => {
    return (
      <label className={cn("relative flex items-center gap-3 w-full rounded-xl border transition-colors duration-300 bg-black/40 backdrop-blur-md px-4 py-3 cursor-pointer select-none group", 
        props.checked ? "border-indigo-500/50 shadow-[0_0_20px_-5px_rgba(99,102,241,0.2)]" : "border-white/10 hover:bg-white/5",
        className
      )}>
        <div className={cn("relative w-5 h-5 flex items-center justify-center rounded-full border transition-colors duration-200",
          props.checked ? "border-indigo-500" : "bg-black/50 border-white/20 group-hover:border-white/40"
        )}>
          <input
            type="radio"
            ref={ref}
            className="sr-only"
            {...props}
          />
          <motion.div
            initial={false}
            animate={{ 
              scale: props.checked ? 1 : 0, 
              opacity: props.checked ? 1 : 0 
            }}
            transition={{ type: "spring", stiffness: 400, damping: 25 }}
            className="w-2.5 h-2.5 rounded-full bg-indigo-500"
          />
        </div>
        <span className={cn("text-sm transition-colors duration-200", props.checked ? "text-white" : "text-zinc-400")}>
          {label}
        </span>
      </label>
    );
  }
);
FloatingRadio.displayName = "FloatingRadio";

"use client";

import * as React from "react";
import { format } from "date-fns";
import { Calendar as CalendarIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

export interface DatePickerProps extends React.HTMLAttributes<HTMLDivElement> {
  date?: Date;
  onDateChange?: (date: Date | undefined) => void;
  placeholder?: string;
}

export function DatePicker({
  className,
  date,
  onDateChange,
  placeholder = "Pick a date",
}: DatePickerProps) {
  const [internalDate, setInternalDate] = React.useState<Date | undefined>(date);

  const activeDate = date !== undefined ? date : internalDate;
  
  const handleSelect = (newDate: Date | undefined) => {
    if (onDateChange) {
      onDateChange(newDate);
    } else {
      setInternalDate(newDate);
    }
  };

  return (
    <div className={cn("grid gap-2", className)}>
      <Popover>
        <PopoverTrigger asChild>
          <Button
            variant={"outline"}
            className={cn(
              "w-[280px] justify-start text-left font-normal",
              !activeDate && "text-muted-foreground"
            )}
          >
            <CalendarIcon className="mr-2 h-4 w-4" />
            {activeDate ? format(activeDate, "PPP") : <span>{placeholder}</span>}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-0" align="start">
          <Calendar
            mode="single"
            selected={activeDate}
            onSelect={handleSelect}
            initialFocus
          />
        </PopoverContent>
      </Popover>
    </div>
  );
}

"use client"

import * as React from "react"
import * as PopoverPrimitive from "@radix-ui/react-popover"

import { cn } from "@/lib/utils"

const Popover = PopoverPrimitive.Root

const PopoverTrigger = PopoverPrimitive.Trigger

const PopoverContent = React.forwardRef<
  React.ElementRef<typeof PopoverPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content>
>(({ className, align = "center", sideOffset = 4, ...props }, ref) => (
  <PopoverPrimitive.Portal>
    <PopoverPrimitive.Content
      ref={ref}
      align={align}
