export function HorizontalScrollHijack({ 
  children, 
  className,
  scrollHeight = "400vh"
}: HorizontalScrollHijackProps) {
  const targetRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
