"use client";

import React, { useMemo, useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Line, Sparkles, OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import { cn } from "@/lib/utils";

export interface WebGLLineChartProps {
  data: number[];
  color?: string;
  className?: string;
}

function ChartLine({ data, color = "#8b5cf6" }: { data: number[], color?: string }) {
  const lineRef = useRef<any>(null);

  const points = useMemo(() => {
    if (!data || data.length === 0) return [new THREE.Vector3(0, 0, 0), new THREE.Vector3(1, 1, 0)];
    
    const max = Math.max(...data);
    const min = Math.min(...data);
    const range = max - min || 1;
    
    const pts = [];
    for (let i = 0; i < data.length; i++) {
      // Map x from -5 to 5
      const x = (i / (data.length - 1)) * 10 - 5;
      // Map y from -2 to 2
      const y = ((data[i] - min) / range) * 4 - 2;
      pts.push(new THREE.Vector3(x, y, 0));
    }
    return pts;
  }, [data]);

  useFrame((state) => {
    if (lineRef.current) {
      // Animate the line drawing in by modulating dashOffset
      if (lineRef.current.material.dashOffset > 0) {
        lineRef.current.material.dashOffset -= 0.02;
      }
    }
  });

  return (
    <group>
      {/* The neon glowing line */}
      <Line
        ref={lineRef}
        points={points}
        color={color}
        lineWidth={5}
        dashed={true}
        dashSize={100} // make dashSize large enough to cover the whole line
        dashOffset={100} // start fully hidden
        dashScale={1}
      />
      {/* Background glow using a wider, transparent line */}
      <Line
        points={points}
        color={color}
        lineWidth={20}
        transparent
        opacity={0.15}
      />
      {/* Particles emitting along the line */}
      <Sparkles 
        count={50} 
        scale={[10, 4, 2]} 
        color={color} 
        size={2} 
        speed={0.4} 
        opacity={0.5} 
      />
    </group>
  );
}

export function WebGLLineChart({ data, color = "#8b5cf6", className }: WebGLLineChartProps) {
  return (
    <div className={cn("w-full h-[400px] bg-black rounded-xl overflow-hidden relative", className)}>
      <Canvas camera={{ position: [0, 0, 8], fov: 50 }}>
        <ambientLight intensity={0.5} />
        <ChartLine data={data} color={color} />
        {/* Allow users to slightly rotate the chart for a 3D effect */}
        <OrbitControls 
          enableZoom={false} 
          enablePan={false} 
          minAzimuthAngle={-0.2} 
          maxAzimuthAngle={0.2}
          minPolarAngle={Math.PI / 2 - 0.2}
          maxPolarAngle={Math.PI / 2 + 0.2}
        />
      </Canvas>
      <div className="absolute top-4 left-4 pointer-events-none">
        <h3 className="text-white font-semibold text-lg tracking-tight">Revenue (3D)</h3>
        <p className="text-zinc-500 text-sm">Interactive WebGL Visualization</p>
      </div>
    </div>
  );
}

"use client";

import React, { useRef, useState, useEffect } from "react";
import { motion, useSpring, useMotionValue, useTransform, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";

export interface MagneticTooltipProps {
  children: React.ReactNode;
  content: string | React.ReactNode;
  className?: string;
  tooltipClassName?: string;
}

export function MagneticTooltip({
  children,
  content,
  className,
  tooltipClassName,
}: MagneticTooltipProps) {
  const [isHovered, setIsHovered] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);

  // Mouse position relative to the container
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  // Physics springs for smooth, magnetic movement
  const springX = useSpring(mouseX, { stiffness: 150, damping: 15, mass: 0.1 });
  const springY = useSpring(mouseY, { stiffness: 150, damping: 15, mass: 0.1 });

  // Calculate velocity for stretching effect
  const velocityX = useMotionValue(0);
  const velocityY = useMotionValue(0);
  
  useEffect(() => {
    let lastX = springX.get();
    let lastY = springY.get();
    let lastTime = Date.now();

    const unsubscribeX = springX.on("change", (v) => {
      const now = Date.now();
      const dt = Math.max(1, now - lastTime);
      velocityX.set((v - lastX) / dt);
      lastX = v;
      lastTime = now;
    });

    const unsubscribeY = springY.on("change", (v) => {
      const now = Date.now();
      const dt = Math.max(1, now - lastTime);
      velocityY.set((v - lastY) / dt);
      lastY = v;
      lastTime = now;
    });

    return () => {
      unsubscribeX();
      unsubscribeY();
    };
  }, [springX, springY, velocityX, velocityY]);

  // Transform velocity into rotation and scale (squash & stretch)
  const stretchX = useTransform(velocityX, [-5, 0, 5], [1.2, 1, 1.2]);
  const stretchY = useTransform(velocityY, [-5, 0, 5], [1.2, 1, 1.2]);
  const rotation = useTransform(velocityX, [-5, 5], [-15, 15]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current || !tooltipRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const tooltipRect = tooltipRef.current.getBoundingClientRect();
    
    // Center the tooltip on the cursor
    const x = e.clientX - rect.left - tooltipRect.width / 2;
    // Offset above the cursor
    const y = e.clientY - rect.top - tooltipRect.height - 20;

    mouseX.set(x);
    mouseY.set(y);
  };

  return (
    <div
      ref={containerRef}
      className={cn("relative inline-block", className)}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onMouseMove={handleMouseMove}
    >
      {children}

      <AnimatePresence>
        {isHovered && (
          <motion.div
            ref={tooltipRef}
            initial={{ opacity: 0, scale: 0.8, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.8, y: 10 }}
            transition={{ type: "spring", stiffness: 300, damping: 20 }}
            className={cn(
              "absolute top-0 left-0 z-50 pointer-events-none px-4 py-2 rounded-xl bg-black text-white text-sm font-medium shadow-xl border border-white/10 whitespace-nowrap",
              tooltipClassName
            )}
            style={{
              x: springX,
              y: springY,
              scaleX: stretchX,
              scaleY: stretchY,
              rotate: rotation,
              transformOrigin: "bottom center",
            }}
          >
            {content}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { motion, useAnimation } from "framer-motion";
import { cn } from "@/lib/utils";

interface CyberSpeedometerProps {
  value: number; // 0 to 100
  label?: string;
  className?: string;
}

export function CyberSpeedometer({ value, label = "SYSTEM LOAD", className }: CyberSpeedometerProps) {
  const [displayValue, setDisplayValue] = useState(0);

  // Constrain value
  const safeValue = Math.max(0, Math.min(100, value));

  // Calculate SVG stroke parameters
  const radius = 120;
  const circumference = 2 * Math.PI * radius;
  // We want a gauge that goes from -225 deg to 45 deg (270 degrees total span)
  const arcSpan = 270;
  const strokeDashoffset = circumference - ((safeValue / 100) * (arcSpan / 360) * circumference);

  // Determine color based on value thresholds
  const isWarning = safeValue > 85;
  const glowColor = isWarning ? "#ef4444" : "#0ea5e9";
  const strokeColor = isWarning ? "rgba(239,68,68,1)" : "rgba(14,165,233,1)";

  // Animate the text numbers rolling up
  useEffect(() => {
    let startTimestamp: number;
    const duration = 1000;
    const startValue = displayValue;

    const step = (timestamp: number) => {
      if (!startTimestamp) startTimestamp = timestamp;
      const progress = Math.min((timestamp - startTimestamp) / duration, 1);

      // Easing function (easeOutExpo)
      const easeProgress = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);

      const current = Math.floor(startValue + (safeValue - startValue) * easeProgress);
      setDisplayValue(current);

      if (progress < 1) {
        window.requestAnimationFrame(step);
      }
    };

    window.requestAnimationFrame(step);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [safeValue]);

  return (
    <div className={cn("relative flex items-center justify-center font-mono", className)}>
      <svg width={300} height={300} className="transform -rotate-90">
        <defs>
          <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="8" result="coloredBlur"/>
            <feMerge>
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        {/* Background Track */}
        <circle
          cx="150"
          cy="150"
          r={radius}
          fill="none"
          stroke="rgba(255,255,255,0.05)"
          strokeWidth="20"
          strokeDasharray={circumference}
          strokeDashoffset={circumference * ((360 - arcSpan) / 360)}
          strokeLinecap="round"
          className="transform origin-center rotate-[135deg]"
        />

        {/* Tick Marks */}
        <g className="transform origin-center rotate-[135deg]">
          {[...Array(28)].map((_, i) => {
            const angle = (i / 27) * arcSpan;
            const isRedZone = angle > (arcSpan * 0.85); // last 15% is red
            return (
              <line
                key={i}
                x1="150"
                y1="30"
                x2="150"
                y2={i % 3 === 0 ? "15" : "24"} // major vs minor ticks
                stroke={isRedZone ? "rgba(239,68,68,0.5)" : "rgba(255,255,255,0.2)"}
                strokeWidth={i % 3 === 0 ? 3 : 1}
                transform={`rotate(${angle} 150 150)`}
              />
            );
          })}
        </g>

        {/* Animated Fill Track */}
        <motion.circle
          cx="150"
          cy="150"
          r={radius}
          fill="none"
          stroke={strokeColor}
          strokeWidth="12"
          strokeLinecap="round"
          strokeDasharray={circumference}
          initial={{ strokeDashoffset: circumference }}
          animate={{ strokeDashoffset }}
          transition={{ duration: 1, type: "spring", bounce: 0, damping: 20 }}
          className="transform origin-center rotate-[135deg]"
          filter="url(#neon-glow)"
        />
      </svg>

      {/* Center Readout */}
      <div className="absolute inset-0 flex flex-col items-center justify-center pt-8">
        <span 
          className="text-6xl font-bold tracking-tighter"
          style={{ 
            color: strokeColor,
            textShadow: `0 0 20px ${glowColor}` 
          }}
        >
          {displayValue}
        </span>
        <span className="text-neutral-500 text-xs tracking-[0.2em] mt-1">{label}</span>
      </div>
    </div>
  );
}

