"use client";

import React, { useMemo, useState } from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

export interface SvgIsometricGridProps {
  className?: string;
  gridSize?: number;
  spacing?: number;
  dotRadius?: number;
}

export function SvgIsometricGrid({
  className,
  gridSize = 10,
  spacing = 30,
  dotRadius = 2,
}: SvgIsometricGridProps) {
  const [rippleOrigin, setRippleOrigin] = useState<{ x: number, y: number } | null>(null);
  const [rippleKey, setRippleKey] = useState(0);

  // Generate grid points
  const points = useMemo(() => {
    const pts = [];
    for (let x = 0; x < gridSize; x++) {
      for (let y = 0; y < gridSize; y++) {
        // Isometric projection math (pseudo)
        const isoX = (x - y) * spacing;
        const isoY = ((x + y) * spacing) / 2;
        pts.push({ gridX: x, gridY: y, isoX, isoY });
      }
    }
    return pts;
  }, [gridSize, spacing]);

  const handleDotClick = (gridX: number, gridY: number) => {
    setRippleOrigin({ x: gridX, y: gridY });
    setRippleKey((prev) => prev + 1);
  };

  return (
    <div className={cn("relative w-full h-full flex items-center justify-center overflow-hidden", className)}>
      <motion.svg
        // The viewBox ensures the isometric diamond fits
        viewBox="-400 -100 800 400"
        className="w-full h-full"
      >
        {points.map((p, i) => {
          // Calculate distance from ripple origin
          let delay = 0;
          if (rippleOrigin) {
            const dx = p.gridX - rippleOrigin.x;
            const dy = p.gridY - rippleOrigin.y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            delay = distance * 0.05; // speed of the ripple
          }

          return (
            <motion.circle
              key={`${p.gridX}-${p.gridY}-${rippleKey}`}
              cx={p.isoX}
              cy={p.isoY}
              r={dotRadius}
              fill="currentColor"
              className="text-zinc-500 hover:text-white cursor-pointer transition-colors"
              onClick={() => handleDotClick(p.gridX, p.gridY)}
              
              // Ripple animation
              initial={{ y: 0 }}
              animate={rippleOrigin ? { y: [0, -30, 0] } : { y: 0 }}
              transition={{
                duration: 0.6,
                delay: delay,
                ease: "easeInOut",
              }}
            />
          );
        })}

        {/* Draw connection lines to form the grid */}
        {points.map((p) => {
          // Find neighbors
          const rightNeighbor = points.find(n => n.gridX === p.gridX + 1 && n.gridY === p.gridY);
          const bottomNeighbor = points.find(n => n.gridX === p.gridX && n.gridY === p.gridY + 1);

          return (
            <React.Fragment key={`lines-${p.gridX}-${p.gridY}`}>
              {rightNeighbor && (
                <line
                  x1={p.isoX}
                  y1={p.isoY}
                  x2={rightNeighbor.isoX}
                  y2={rightNeighbor.isoY}
                  stroke="rgba(255,255,255,0.05)"
                  strokeWidth={1}
                  className="pointer-events-none"
                />
              )}
              {bottomNeighbor && (
                <line
                  x1={p.isoX}
                  y1={p.isoY}
                  x2={bottomNeighbor.isoX}
                  y2={bottomNeighbor.isoY}
                  stroke="rgba(255,255,255,0.05)"
                  strokeWidth={1}
                  className="pointer-events-none"
                />
              )}
            </React.Fragment>
          );
        })}
      </motion.svg>
    </div>
  );
}

"use client";

import React, { useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Html, Float, Environment, ContactShadows, SpotLight } from "@react-three/drei";
import * as THREE from "three";
import { cn } from "@/lib/utils";

export interface HologramDisplayProps {
  children: React.ReactNode;
  className?: string;
  color?: string;
}

function HologramMesh({ children, color = "#06b6d4" }: HologramDisplayProps) {
  const groupRef = useRef<THREE.Group>(null);
  const lightRef = useRef<THREE.SpotLight>(null);

  useFrame((state) => {
    if (groupRef.current) {
      // Very slow rotation of the holographic UI
      groupRef.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.5) * 0.1;
      groupRef.current.position.y = Math.sin(state.clock.elapsedTime * 2) * 0.1 + 1.5;
    }
  });

  return (
    <group>
      {/* Hologram Projector Base */}
      <mesh position={[0, 0, 0]} castShadow receiveShadow>
        <cylinderGeometry args={[1.5, 1.8, 0.5, 32]} />
        <meshStandardMaterial color="#111" metalness={0.9} roughness={0.2} />
      </mesh>
      
      {/* Inner glowing lens */}
      <mesh position={[0, 0.26, 0]}>
        <cylinderGeometry args={[1.2, 1.2, 0.1, 32]} />
        <meshBasicMaterial color={color} transparent opacity={0.8} />
      </mesh>

      {/* Volumetric Light Cone approximation */}
      <mesh position={[0, 2.5, 0]}>
        <cylinderGeometry args={[2.5, 1.2, 5, 32, 1, true]} />
        <meshBasicMaterial 
          color={color} 
          transparent 
          opacity={0.15} 
          side={THREE.DoubleSide} 
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>

      {/* The floating Hologram UI */}
      <group ref={groupRef}>
        <Html 
          transform 
          wrapperClass="hologram-html" 
          distanceFactor={6} 
          zIndexRange={[100, 0]}
          occlude="blending"
        >
          <div 
            className="w-[400px] h-[500px] relative pointer-events-auto"
            style={{
              filter: `drop-shadow(0 0 20px ${color}) drop-shadow(0 0 40px ${color})`,
            }}
          >
            {/* Scanline overlay for holo effect */}
            <div className="absolute inset-0 pointer-events-none z-50 mix-blend-overlay opacity-30 bg-[linear-gradient(to_bottom,transparent_50%,rgba(0,0,0,0.5)_51%)] bg-[length:100%_4px]" />
            {children}
          </div>
        </Html>
      </group>

      {/* Dynamic Lighting */}
      <SpotLight 
        ref={lightRef as any}
        position={[0, 0.5, 0]} 
        angle={0.6} 
        penumbra={1} 
        intensity={20} 
        color={color} 
        distance={10}
        castShadow
      />
    </group>
  );
}

export function HologramDisplay({ children, className, color = "#06b6d4" }: HologramDisplayProps) {
  return (
    <div className={cn("w-full h-[600px] relative bg-black rounded-xl overflow-hidden", className)}>
      <Canvas camera={{ position: [0, 4, 10], fov: 45 }}>
        <color attach="background" args={["#050505"]} />
        <ambientLight intensity={0.5} />
        <directionalLight position={[10, 10, 5]} intensity={1} />
        
        <HologramMesh color={color}>
          {children}
        </HologramMesh>

        <ContactShadows position={[0, -0.25, 0]} opacity={0.8} scale={10} blur={2} far={4} />
        <Environment preset="city" />
      </Canvas>
    </div>
  );
}

"use client";

import React, { useRef, useState } from "react";
import { motion, useMotionValue, useSpring } from "framer-motion";
import { cn } from "@/lib/utils";

export interface DisplacementHoverProps {
  image1: string;
  image2: string;
  className?: string;
  intensity?: number;
}

export function DisplacementHover({
  image1,
  image2,
  className,
  intensity = 50,
}: DisplacementHoverProps) {
  const [isHovered, setIsHovered] = useState(false);
  const filterId = React.useId();

  // Mouse tracking for dynamic displacement center
  const mouseX = useMotionValue(0.5);
  const mouseY = useMotionValue(0.5);

  const springX = useSpring(mouseX, { stiffness: 100, damping: 20 });
  const springY = useSpring(mouseY, { stiffness: 100, damping: 20 });

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    mouseX.set(x);
    mouseY.set(y);
  };

  return (
    <div
      className={cn("relative overflow-hidden cursor-pointer", className)}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => {
        setIsHovered(false);
        mouseX.set(0.5);
        mouseY.set(0.5);
      }}
      onMouseMove={handleMouseMove}
    >
      <svg className="absolute w-0 h-0 hidden">
        <defs>
          <filter id={`displacementFilter-${filterId}`}>
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.03"
              numOctaves="3"
              result="noise"
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="noise"
              scale={isHovered ? intensity : 0}
              xChannelSelector="R"
              yChannelSelector="G"
              className="transition-all duration-700 ease-out"
            />
          </filter>
        </defs>
      </svg>

      <motion.div
        className="absolute inset-0 w-full h-full bg-cover bg-center"
        style={{
          backgroundImage: `url(${image1})`,
          filter: `url(#displacementFilter-${filterId})`,
        }}
        animate={{ opacity: isHovered ? 0 : 1, scale: isHovered ? 1.1 : 1 }}
        transition={{ duration: 0.7, ease: "circOut" }}
      />
      
      <motion.div
        className="absolute inset-0 w-full h-full bg-cover bg-center"
        style={{
          backgroundImage: `url(${image2})`,
          filter: `url(#displacementFilter-${filterId})`,
        }}
        animate={{ opacity: isHovered ? 1 : 0, scale: isHovered ? 1 : 1.1 }}
        transition={{ duration: 0.7, ease: "circOut" }}
      />
    </div>
  );
}

"use client";

import React, { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ArrowUp, Sparkles, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import confetti from "canvas-confetti";

export interface AIGenerativeInputProps {
  onSubmit?: (val: string) => void;
  placeholder?: string;
  className?: string;
}

export function AIGenerativeInput({
  onSubmit,
  placeholder = "Ask anything...",
  className,
}: AIGenerativeInputProps) {
  const [value, setValue] = useState("");
  const [isThinking, setIsThinking] = useState(false);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const handleSubmit = () => {
    if (!value.trim() || isThinking) return;
    
    setIsThinking(true);
    
    // Trigger tiny particle explosion on submit
    if (inputRef.current) {
      const rect = inputRef.current.getBoundingClientRect();
      const x = (rect.right - 40) / window.innerWidth;
      const y = (rect.bottom - 20) / window.innerHeight;
      
      confetti({
        particleCount: 30,
        spread: 40,
        origin: { x, y },
        colors: ["#3b82f6", "#8b5cf6", "#ec4899"],
        disableForReducedMotion: true,
        zIndex: 100,
      });
    }

    if (onSubmit) {
      onSubmit(value);
    }

    // Simulate AI thinking time
    setTimeout(() => {
      setIsThinking(false);
      setValue("");
    }, 2000);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <div className={cn("relative w-full max-w-2xl", className)}>
      <motion.div
        layout
        className={cn(
          "relative overflow-hidden rounded-3xl bg-zinc-900 border transition-colors duration-500",
          isThinking ? "border-transparent" : "border-zinc-800 focus-within:border-zinc-700"
        )}
      >
        {/* Animated Thinking Border */}
        <AnimatePresence>
          {isThinking && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 pointer-events-none"
            >
              <div className="absolute inset-[-1px] rounded-3xl bg-[linear-gradient(90deg,#3b82f6,#8b5cf6,#ec4899,#3b82f6)] bg-[length:200%_100%] animate-[gradient_2s_linear_infinite] p-[1px] -z-10" />
            </motion.div>
          )}
        </AnimatePresence>

        <div className="flex flex-col w-full bg-zinc-900 rounded-3xl p-2 relative z-10">
          <textarea
            ref={inputRef}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            disabled={isThinking}
            className="w-full bg-transparent text-white px-4 py-3 min-h-[60px] max-h-[200px] resize-none outline-none placeholder:text-zinc-500 disabled:opacity-50 transition-opacity"
            rows={value.split("\n").length > 1 ? Math.min(value.split("\n").length, 6) : 1}
          />
          
          <div className="flex justify-between items-center px-2 pb-1 mt-2">
            <div className="flex items-center gap-2 text-xs text-zinc-500 font-medium select-none">
              <Sparkles className="w-4 h-4 text-blue-500" />
              <span>Generative AI Engine</span>
            </div>
            
            <button
              onClick={handleSubmit}
              disabled={!value.trim() || isThinking}
              className={cn(
                "p-2 rounded-full flex items-center justify-center transition-all duration-300",
                value.trim() && !isThinking
                  ? "bg-white text-black hover:scale-105"
                  : "bg-zinc-800 text-zinc-500",
                isThinking && "bg-transparent text-blue-500"
              )}
            >
              {isThinking ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <ArrowUp className="w-5 h-5" />
              )}
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  );
}

"use client";

import React, { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

export interface FluidCursorTrailProps {
  className?: string;
  particleColors?: string[];
}

export function FluidCursorTrail({
  className,
  particleColors = ["#3b82f6", "#8b5cf6", "#ec4899", "#10b981"],
}: FluidCursorTrailProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let particles: Particle[] = [];
    let mouseX = window.innerWidth / 2;
    let mouseY = window.innerHeight / 2;
    let animationFrameId: number;

    const resize = () => {
      // Use parent container size if possible, otherwise window
      const parent = canvas.parentElement;
      if (parent) {
        canvas.width = parent.clientWidth;
        canvas.height = parent.clientHeight;
      } else {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }
    };
    resize();
    window.addEventListener("resize", resize);

    class Particle {
      x: number;
      y: number;
      size: number;
      color: string;
      speedX: number;
      speedY: number;
      life: number;
      maxLife: number;

      constructor(x: number, y: number) {
        this.x = x;
        this.y = y;
        this.size = Math.random() * 40 + 20; // 20-60px
        this.color = particleColors[Math.floor(Math.random() * particleColors.length)];
        this.speedX = Math.random() * 2 - 1;
        this.speedY = Math.random() * 2 - 1;
        this.maxLife = Math.random() * 40 + 40; // 40-80 frames
        this.life = this.maxLife;
      }

      update() {
        this.x += this.speedX;
        this.y += this.speedY;
        this.life--;
        // Shrink slightly
        if (this.size > 0.2) this.size -= 0.1;
      }

      draw() {
        if (!ctx) return;
        const alpha = Math.max(0, this.life / this.maxLife);
        
        ctx.save();
        ctx.globalAlpha = alpha * 0.5; // Max opacity 0.5 for smoky look
        ctx.globalCompositeOperation = "screen";
        
        // Draw soft glowing circle
        const gradient = ctx.createRadialGradient(
          this.x, this.y, 0,
          this.x, this.y, this.size
        );
        gradient.addColorStop(0, this.color);
        gradient.addColorStop(1, "transparent");

        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    }

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouseX = e.clientX - rect.left;
      mouseY = e.clientY - rect.top;
      
      // Spawn 2-3 particles per mouse move event
      for (let i = 0; i < 3; i++) {
        particles.push(new Particle(mouseX, mouseY));
      }
    };

    window.addEventListener("mousemove", handleMouseMove);

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (let i = 0; i < particles.length; i++) {
        particles[i].update();
        particles[i].draw();
        
        if (particles[i].life <= 0 || particles[i].size <= 0) {
          particles.splice(i, 1);
          i--;
        }
      }

      animationFrameId = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      window.removeEventListener("resize", resize);
      window.removeEventListener("mousemove", handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, [particleColors]);

  return (
    <canvas
      ref={canvasRef}
      className={cn("pointer-events-none absolute inset-0 z-50", className)}
    />
  );
}

"use client";

import React, { useRef } from "react";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";

export interface SoftBodyJellyProps {
  className?: string;
}

export function SoftBodyJelly({ className }: SoftBodyJellyProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  
  // Track relative drag position
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  // Apply heavy spring physics to give it that "jelly" weight
  const springConfig = { damping: 10, stiffness: 100, mass: 2 };
  const springX = useSpring(x, springConfig);
  const springY = useSpring(y, springConfig);

  // Convert the spring physics into path coordinates for an SVG bezier curve
  // A standard circle/blob in SVG using absolute coordinates
  // We'll morph the control points based on drag tension
  const path = useTransform([springX, springY], ([latestX, latestY]: any) => {
    // Max deformation cap
    const dx = Math.max(-50, Math.min(50, latestX * 0.5));
    const dy = Math.max(-50, Math.min(50, latestY * 0.5));

    // Base coordinates for a 100x100 blob
    // M 50,0 C 77,0 100,23 100,50 C 100,77 77,100 50,100 C 23,100 0,77 0,50 C 0,23 23,0 50,0
    
    // We deform the center points based on drag
    return `M 50,0 
            C ${77 + dx},0 ${100 + dx},23 ${100 + dx},50 
            C ${100 + dx},77 ${77 + dx},100 50,100 
            C ${23 + dx},100 ${0 + dx},77 ${0 + dx},50 
            C ${0 + dx},23 ${23 + dx},0 50,0 Z`;
  });

  return (
    <div 
      ref={containerRef}
      className={cn("relative flex items-center justify-center w-64 h-64", className)}
    >
      {/* Invisible drag target that maps to the spring values */}
      <motion.div
        drag
        dragConstraints={containerRef}
        dragElastic={0.4}
        style={{ x, y }}
        className="absolute w-32 h-32 z-20 cursor-grab active:cursor-grabbing"
      />

      {/* The physical rendered jelly */}
      <motion.svg
        viewBox="-20 -20 140 140"
        className="w-full h-full absolute inset-0 pointer-events-none drop-shadow-[0_0_30px_rgba(236,72,153,0.5)]"
      >
        <defs>
          <linearGradient id="jelly-grad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#ec4899" />
            <stop offset="100%" stopColor="#8b5cf6" />
          </linearGradient>
        </defs>
        
        {/* We use framer-motion's motion.path to natively animate the 'd' attribute string */}
        <motion.path
          d={path as any}
          fill="url(#jelly-grad)"
          className="transition-colors"
        />
      </motion.svg>
      
      <span className="relative z-10 font-bold text-white pointer-events-none drop-shadow-md">
        Drag Me
      </span>
    </div>
  );
}

"use client";

import React, { useRef, useCallback } from "react";
import { motion, HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

export interface GenerativeAudioBtnProps extends HTMLMotionProps<"button"> {
  children: React.ReactNode;
  soundType?: "click" | "glitch" | "pop";
}

export function GenerativeAudioBtn({
  children,
  className,
  soundType = "click",
  ...props
}: GenerativeAudioBtnProps) {
  // Use a ref to store the AudioContext so we reuse it
  const audioCtxRef = useRef<AudioContext | null>(null);

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    // Resume context if it was suspended (browser policy)
    if (audioCtxRef.current.state === "suspended") {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  const playSound = useCallback((type: "down" | "up") => {
    try {
      const ctx = getAudioContext();
      const osc = ctx.createOscillator();
      const gainNode = ctx.createGain();

      osc.connect(gainNode);
      gainNode.connect(ctx.destination);

      const now = ctx.currentTime;

      if (soundType === "click") {
        // A mechanical, high-tech click
        osc.type = "sine";
        if (type === "down") {
          osc.frequency.setValueAtTime(600, now);
          osc.frequency.exponentialRampToValueAtTime(100, now + 0.05);
          gainNode.gain.setValueAtTime(1, now);
          gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
          osc.start(now);
          osc.stop(now + 0.05);
        } else {
          osc.frequency.setValueAtTime(800, now);
          osc.frequency.exponentialRampToValueAtTime(200, now + 0.05);
          gainNode.gain.setValueAtTime(0.5, now);
          gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
          osc.start(now);
          osc.stop(now + 0.05);
        }
      } else if (soundType === "pop") {
        // A bubbly pop sound
        osc.type = "sine";
        osc.frequency.setValueAtTime(type === "down" ? 400 : 500, now);
        osc.frequency.exponentialRampToValueAtTime(type === "down" ? 600 : 700, now + 0.1);
        gainNode.gain.setValueAtTime(0, now);
        gainNode.gain.linearRampToValueAtTime(1, now + 0.02);
        gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
        osc.start(now);
        osc.stop(now + 0.1);
      } else if (soundType === "glitch") {
        // A sci-fi glitchy zap
        osc.type = "sawtooth";
        osc.frequency.setValueAtTime(type === "down" ? 150 : 250, now);
        osc.frequency.linearRampToValueAtTime(type === "down" ? 50 : 100, now + 0.1);
        
        // Add a simple lowpass filter
        const filter = ctx.createBiquadFilter();
        filter.type = "lowpass";
        filter.frequency.setValueAtTime(2000, now);
        filter.frequency.exponentialRampToValueAtTime(200, now + 0.1);
        
        osc.disconnect();
        osc.connect(filter);
        filter.connect(gainNode);

        gainNode.gain.setValueAtTime(0.8, now);
        gainNode.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
        osc.start(now);
        osc.stop(now + 0.1);
      }
    } catch (e) {
      console.error("Web Audio API not supported or blocked", e);
    }
  }, [soundType]);

  return (
    <motion.button
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.95 }}
      onPointerDown={() => playSound("down")}
      onPointerUp={() => playSound("up")}
      onPointerLeave={() => {
        // Optional: cancel any state if needed
      }}
      className={cn(
        "relative px-6 py-3 rounded-lg font-medium text-white bg-zinc-900 border border-zinc-800 shadow-xl overflow-hidden transition-colors hover:bg-zinc-800",
        className
      )}
      {...props}
    >
      <span className="relative z-10">{children}</span>
    </motion.button>
  );
}

"use client";

import React, { useRef, useState } from "react";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";

export interface PluckableStringProps {
  className?: string;
  strokeWidth?: number;
  strokeColor?: string;
}

export function PluckableString({
  className,
  strokeWidth = 2,
  strokeColor = "rgba(255, 255, 255, 0.4)",
}: PluckableStringProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  
  // y position of the string center
  const y = useMotionValue(50);
  const [isHovered, setIsHovered] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtxRef.current.state === "suspended") {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  const playPluckSound = (pullDistance: number) => {
    try {
      const ctx = getAudioContext();
      const osc = ctx.createOscillator();
      const gainNode = ctx.createGain();

      osc.connect(gainNode);
      gainNode.connect(ctx.destination);

      const now = ctx.currentTime;
      
      // The further you pull it, the higher the tension/pitch
      const baseFreq = 200;
      const pitchOffset = Math.abs(pullDistance - 50) * 2;
      
      osc.type = "triangle"; // Triangle sounds a bit like a string
      osc.frequency.setValueAtTime(baseFreq + pitchOffset, now);
      // Slight pitch bend down as it vibrates
      osc.frequency.exponentialRampToValueAtTime(baseFreq, now + 0.5);

      // Snappy attack, long bouncy decay
      gainNode.gain.setValueAtTime(0, now);
      gainNode.gain.linearRampToValueAtTime(0.8, now + 0.02);
      gainNode.gain.exponentialRampToValueAtTime(0.001, now + 0.5);

      osc.start(now);
      osc.stop(now + 0.5);
    } catch (e) {
      console.error("Web Audio API error", e);
    }
  };

  // An underdamped, highly bouncy spring to simulate the "pluck" vibration
  const springY = useSpring(y, {
    stiffness: 500,
    damping: 5,   // low damping = lots of wobble
    mass: 1,
  });

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    
    // Calculate relative Y position, clamped slightly
    const relativeY = e.clientY - rect.top;
    y.set(relativeY);
    setIsHovered(true);
  };

  const handleMouseLeave = () => {
    // Play the twang sound based on how far we pulled it
    playPluckSound(y.get());
    
    // Snap back to center (50) to trigger the massive spring vibration
    y.set(50);
    setIsHovered(false);
  };

  // Convert the spring Y value into an SVG Quadratic Bezier Curve
  // M 0,50 Q 50,Y 100,50
  const path = useTransform(springY, (latestY: number) => {
    // Clamp the deformation so it doesn't break out of the SVG box
    const clampedY = Math.max(0, Math.min(100, latestY));
    return `M 0,50 Q 50,${clampedY} 100,50`;
  });

  return (
    <div
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className={cn("relative w-full h-24 flex items-center justify-center cursor-crosshair", className)}
    >
      <motion.svg
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        className="w-full h-full absolute inset-0 pointer-events-none"
      >
        <motion.path
          d={path as any}
          stroke={isHovered ? "#fff" : strokeColor}
          strokeWidth={strokeWidth}
          fill="transparent"
          strokeLinecap="round"
          className="transition-colors duration-200"
        />
      </motion.svg>
    </div>
  );
}

