            exit={{ opacity: 0 }}
            onClick={() => {
              setIsOpen(false);
              setTimeout(() => setStep(1), 500);
            }}
            className="fixed inset-0 bg-black/20 backdrop-blur-sm z-40"
          />
        )}
      </AnimatePresence>
    </div>
  );
