          )}
        </div>
      </div>

      <AnimatePresence initial={false}>
        {hasChildren && isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3, ease: "easeInOut" }}
            className="overflow-hidden"
          >
            <div className="pl-12 pb-2 space-y-2">
              {step.children!.map((child, idx) => (
                <TreeNode 
                  key={child.id} 
                  step={child} 
                  isLast={idx === step.children!.length - 1} 
                />
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export function ReasoningTree({ steps = DEMO_THOUGHTS, className }: ReasoningTreeProps) {
  return (
    <div className={cn("w-full bg-neutral-950 p-6 rounded-xl border border-white/10 font-sans", className)}>
      <div className="flex items-center gap-2 mb-6 text-sm font-medium text-neutral-400">
        <BrainCircuit size={16} className="text-indigo-400" />
        <span>Chain of Thought</span>
      </div>

      <div className="space-y-4">
        {steps.map((step, idx) => (
          <TreeNode key={step.id} step={step} isLast={idx === steps.length - 1} />
        ))}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useRef, useEffect } from "react";
import { motion, useMotionValue, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";
import { GripVertical, Bot, Sparkles } from "lucide-react";

interface LlmCompareSliderProps {
  modelA_Name?: string;
  modelB_Name?: string;
  modelA_Content?: React.ReactNode;
  modelB_Content?: React.ReactNode;
  className?: string;
}

export function LlmCompareSlider({
  modelA_Name = "GPT-4",
  modelB_Name = "Claude 3 Opus",
  modelA_Content,
  modelB_Content,
  className,
}: LlmCompareSliderProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [sliderPosition, setSliderPosition] = useState(50); // percentage 0-100
  const [isDragging, setIsDragging] = useState(false);

  // Fallback demo content
  const defaultContentA = (
    <div className="space-y-4">
      <p>Here is a generic explanation of quantum computing:</p>
      <p>Quantum computing is a rapidly-emerging technology that harnesses the laws of quantum mechanics to solve problems too complex for classical computers.</p>
      <div className="p-3 bg-neutral-900 rounded-md border border-neutral-800 font-mono text-sm text-neutral-300">
        Time: 2.4s | Tokens: 45
      </div>
    </div>
  );

  const defaultContentB = (
    <div className="space-y-4">
      <p>Here is an <span className="text-emerald-400 bg-emerald-400/10 px-1 rounded">intuitive</span> explanation of quantum computing:</p>
      <p>Think of classical computing as a coin that can only show <span className="text-emerald-400 bg-emerald-400/10 px-1 rounded">Heads or Tails</span>. Quantum computing is like a coin <span className="text-emerald-400 bg-emerald-400/10 px-1 rounded">spinning in the air</span>—it can represent multiple states simultaneously.</p>
      <div className="p-3 bg-neutral-900 rounded-md border border-neutral-800 font-mono text-sm text-neutral-300">
        Time: 1.8s | Tokens: 62
      </div>
    </div>
  );

  const contentA = modelA_Content || defaultContentA;
  const contentB = modelB_Content || defaultContentB;

  const handlePointerDown = (e: React.PointerEvent) => {
    setIsDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDragging(false);
    e.currentTarget.releasePointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  return (
    <div 
      ref={containerRef}
      className={cn(
        "relative w-full h-[400px] select-none rounded-xl overflow-hidden border border-white/10 bg-neutral-950 font-sans",
        className
      )}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerUp}
    >
      {/* Background Layer: Model A */}
      <div className="absolute inset-0 p-6 flex flex-col bg-neutral-950 text-neutral-200">
        <div className="flex items-center gap-2 mb-6 pb-4 border-b border-white/10 text-neutral-400">
          <Bot size={18} />
          <span className="font-semibold">{modelA_Name}</span>
        </div>
        <div className="flex-1 pr-6 max-w-[90%]">
          {contentA}
        </div>
      </div>

      {/* Foreground Layer: Model B (clipped) */}
      <div 
        className="absolute inset-0 p-6 flex flex-col bg-neutral-900 text-neutral-200 pointer-events-none border-r border-indigo-500/30 shadow-[4px_0_24px_rgba(0,0,0,0.5)]"
        style={{
          clipPath: `polygon(0 0, ${sliderPosition}% 0, ${sliderPosition}% 100%, 0 100%)`
        }}
      >
        <div className="flex items-center gap-2 mb-6 pb-4 border-b border-white/10 text-indigo-300">
          <Sparkles size={18} />
          <span className="font-semibold">{modelB_Name}</span>
        </div>
        <div className="flex-1 pr-6 max-w-[90%]">
          {contentB}
        </div>
      </div>

      {/* Slider Handle */}
      <div
        className="absolute top-0 bottom-0 w-1 bg-indigo-500 cursor-ew-resize hover:bg-indigo-400 transition-colors"
        style={{ left: `calc(${sliderPosition}% - 2px)` }}
      >
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-12 bg-indigo-600 rounded-md flex items-center justify-center shadow-lg border border-indigo-400">
          <GripVertical size={16} className="text-white" />
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence, useDragControls } from "framer-motion";
import { cn } from "@/lib/utils";
import { GripHorizontal, X } from "lucide-react";

interface ElasticDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  children?: React.ReactNode;
  title?: string;
  className?: string;
}

export function ElasticDrawer({
  isOpen,
  onClose,
  children,
  title = "Details",
  className,
}: ElasticDrawerProps) {
  const dragControls = useDragControls();

  // Prevent background scrolling when drawer is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isOpen]);

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm"
          />

          {/* Drawer */}
          <motion.div
            initial={{ y: "100%" }}
            animate={{ y: 0 }}
            exit={{ y: "100%" }}
            transition={{
              type: "spring",
              damping: 25,
              stiffness: 200,
              mass: 0.8,
            }}
            drag="y"
            dragControls={dragControls}
            dragListener={false} // Only allow dragging from the handle area
            dragConstraints={{ top: 0, bottom: 0 }}
            dragElastic={0.4} // The rubber-band effect!
            onDragEnd={(e, info) => {
              if (info.offset.y > 100 || info.velocity.y > 500) {
                onClose();
              }
            }}
            className={cn(
              "fixed bottom-0 left-0 right-0 z-50 h-[80vh] flex flex-col bg-neutral-900 border-t border-white/10 rounded-t-3xl shadow-2xl font-sans",
              className
            )}
          >
            {/* Drag Handle Area */}
            <div 
              className="w-full pt-4 pb-2 flex justify-center cursor-grab active:cursor-grabbing touch-none"
              onPointerDown={(e) => dragControls.start(e)}
            >
              <div className="w-12 h-1.5 bg-white/20 rounded-full" />
            </div>

            {/* Header */}
            <div className="flex items-center justify-between px-6 pb-4 border-b border-white/10">
              <h2 className="text-xl font-bold text-white">{title}</h2>
              <button 
                onClick={onClose}
                className="p-2 rounded-full hover:bg-white/10 text-neutral-400 hover:text-white transition-colors"
              >
                <X size={20} />
              </button>
            </div>

            {/* Scrollable Content */}
            <div className="flex-1 overflow-y-auto p-6 text-neutral-300">
              {children || (
                <div className="space-y-6">
                  <p>
                    This is an elastic drawer component powered by Framer Motion. Try grabbing the handle at the top and pulling it upwards to feel the <strong>rubber-band elastic overscroll resistance</strong>, just like native iOS sheets!
                  </p>
                  <div className="grid grid-cols-2 gap-4">
                    {[...Array(6)].map((_, i) => (
                      <div key={i} className="h-32 bg-white/5 rounded-xl border border-white/5 animate-pulse" style={{ animationDelay: `${i * 0.1}s` }} />
                    ))}
                  </div>
                  <p>
                    Swipe down with velocity or drag past the threshold to snap the drawer closed.
                  </p>
                </div>
              )}
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { motion, useAnimation } from "framer-motion";
import { cn } from "@/lib/utils";

interface ReelProps {
  targetChar: string;
  delay?: number;
  spinning?: boolean;
}

const CHARACTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!?@#$%&";

function SingleReel({ targetChar, delay = 0, spinning = false }: ReelProps) {
  const controls = useAnimation();

  // We create a very tall strip of characters.
  // The first characters are random blurriness, the last character is our target.
  const [strip, setStrip] = useState<string[]>([]);

  useEffect(() => {
    // Generate a long strip of 30 random characters, ending with the target
    const newStrip = Array.from({ length: 30 }).map(() => 
      CHARACTERS[Math.floor(Math.random() * CHARACTERS.length)]
    );
    newStrip[newStrip.length - 1] = targetChar;
    setStrip(newStrip);
  }, [targetChar]);

  useEffect(() => {
    if (spinning) {
      // Loop the animation very fast
      controls.start({
        y: [0, -1000], // random big number to create blur
        transition: {
          duration: 0.2,
          ease: "linear",
          repeat: Infinity,
        }
      });
    } else if (!spinning && strip.length > 0) {
      // Spin to the very bottom character (our target)
      // Height of one character cell is ~1em depending on styling. 
      // We'll calculate it using flex col percentage or absolute translation.
      controls.start({
        y: `-${(strip.length - 1) * 100}%`,
        transition: {
          type: "spring",
          damping: 15,
          stiffness: 80,
          mass: 2,
          delay: delay,
        }
      });
    }
  }, [spinning, controls, strip.length, delay]);

  return (
    <div className="relative h-[1.2em] overflow-hidden inline-flex justify-center items-start w-[1em] text-center border-x border-white/5 bg-neutral-900/50">
      <motion.div 
        animate={controls}
        initial={{ y: 0 }}
        className="flex flex-col items-center"
      >
        {strip.map((char, i) => (
          <span 
            key={i} 
            className="h-[1.2em] flex items-center justify-center font-mono font-bold leading-none text-white/90"
          >
            {char}
          </span>
        ))}
      </motion.div>

      {/* Inner Shadow overlay to make it look like a physical barrel reel */}
      <div className="absolute inset-0 pointer-events-none shadow-[inset_0_8px_10px_-4px_rgba(0,0,0,0.8),inset_0_-8px_10px_-4px_rgba(0,0,0,0.8)]" />
    </div>
  );
}

interface SlotMachineReelProps {
  value: string;
  spinning?: boolean;
  className?: string;
}

export function SlotMachineReel({ value, spinning = false, className }: SlotMachineReelProps) {
  const chars = value.split("");

  return (
    <div className={cn("inline-flex items-center text-4xl p-2 rounded-xl bg-neutral-950 border border-white/10 shadow-2xl", className)}>
      {chars.map((char, i) => (
        <React.Fragment key={i}>
          {char === " " ? (
            <span className="w-[0.5em]" />
          ) : (
            <SingleReel 
              targetChar={char} 
              delay={i * 0.15} // Stagger the stopping time
              spinning={spinning} 
            />
          )}
        </React.Fragment>
      ))}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { motion, useAnimation, useMotionValue, useSpring } from "framer-motion";
import { cn } from "@/lib/utils";
import { 
  Github, 
  Twitter, 
  Linkedin, 
  Mail, 
  Figma,
  Code2,
  Cpu
} from "lucide-react";

interface Planet {
  id: string;
  icon: React.ReactNode;
  label: string;
  color: string;
  radius: number; // orbit distance
  speed: number;  // orbit speed multiplier
  angleOffset: number; // initial angle
}

const PLANETS: Planet[] = [
  { id: "p1", icon: <Github size={20} />, label: "GitHub", color: "#ffffff", radius: 100, speed: 1, angleOffset: 0 },
  { id: "p2", icon: <Twitter size={20} />, label: "Twitter", color: "#1da1f2", radius: 100, speed: 1, angleOffset: (Math.PI * 2) / 3 },
  { id: "p3", icon: <Linkedin size={20} />, label: "LinkedIn", color: "#0077b5", radius: 100, speed: 1, angleOffset: (Math.PI * 4) / 3 },
  { id: "p4", icon: <Figma size={18} />, label: "Design", color: "#f24e1e", radius: 160, speed: 0.6, angleOffset: Math.PI / 4 },
  { id: "p5", icon: <Code2 size={18} />, label: "Code", color: "#38bdf8", radius: 160, speed: 0.6, angleOffset: Math.PI + Math.PI / 4 },
];

interface MagneticOrbitMenuProps {
  className?: string;
}

export function MagneticOrbitMenu({ className }: MagneticOrbitMenuProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isHoveringGlobal, setIsHoveringGlobal] = useState(false);
  const [time, setTime] = useState(0);

  // Global timer for orbit paths
  useEffect(() => {
    let animationFrame: number;
    let lastTime = performance.now();

    const loop = (currentTime: number) => {
      const dt = (currentTime - lastTime) / 1000;
      lastTime = currentTime;

      // Pause orbit if hovering anything
      if (!isHoveringGlobal) {
        setTime((t) => t + dt);
      }
      animationFrame = requestAnimationFrame(loop);
    };

    animationFrame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animationFrame);
  }, [isHoveringGlobal]);

  // Handle magnetic cursor pull for the center avatar
  const cursorX = useMotionValue(0);
  const cursorY = useMotionValue(0);

  const springX = useSpring(cursorX, { stiffness: 150, damping: 15, mass: 0.1 });
  const springY = useSpring(cursorY, { stiffness: 150, damping: 15, mass: 0.1 });

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    // Calculate distance from center to cursor
    const x = e.clientX - rect.left - centerX;
    const y = e.clientY - rect.top - centerY;

    cursorX.set(x * 0.2); // dampen the pull
    cursorY.set(y * 0.2);
  };

  const handlePointerLeave = () => {
    cursorX.set(0);
    cursorY.set(0);
  };

  return (
    <div 
      ref={containerRef}
      className={cn("relative w-full h-[500px] bg-neutral-950 flex items-center justify-center overflow-hidden font-sans border border-white/10 rounded-xl", className)}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
    >
      {/* Draw Orbit Rings */}
      <div className="absolute w-[200px] h-[200px] rounded-full border border-white/5" />
      <div className="absolute w-[320px] h-[320px] rounded-full border border-white/5 border-dashed" />

      {/* Center Avatar */}
      <motion.div 
        className="relative z-10 w-24 h-24 rounded-full bg-gradient-to-tr from-indigo-600 to-purple-600 p-1 shadow-[0_0_40px_rgba(79,70,229,0.3)] flex items-center justify-center"
        style={{ x: springX, y: springY }}
        onMouseEnter={() => setIsHoveringGlobal(true)}
        onMouseLeave={() => setIsHoveringGlobal(false)}
      >
        <div className="w-full h-full rounded-full bg-neutral-900 flex items-center justify-center text-white">
          <Cpu size={32} />
        </div>
      </motion.div>

      {/* Orbiting Planets */}
      {PLANETS.map((planet) => {
        // Calculate orbit position using trigonometry
        const currentAngle = planet.angleOffset + (time * planet.speed);

        // Convert polar to cartesian
        const x = Math.cos(currentAngle) * planet.radius;
        const y = Math.sin(currentAngle) * planet.radius;

        return (
          <PlanetNode 
            key={planet.id} 
            planet={planet} 
            x={x} 
            y={y} 
            onHoverStart={() => setIsHoveringGlobal(true)}
            onHoverEnd={() => setIsHoveringGlobal(false)}
          />
        );
      })}
    </div>
  );
}

function PlanetNode({ 
  planet, 
  x, 
  y, 
  onHoverStart, 
  onHoverEnd 
}: { 
  planet: Planet; 
  x: number; 
  y: number;
  onHoverStart: () => void;
  onHoverEnd: () => void;
}) {
  const [isHovered, setIsHovered] = useState(false);

  return (
    <motion.div
      className="absolute"
      animate={{ x, y }}
      transition={{ type: "tween", ease: "linear", duration: 0 }}
      onMouseEnter={() => {
        setIsHovered(true);
        onHoverStart();
      }}
      onMouseLeave={() => {
        setIsHovered(false);
        onHoverEnd();
      }}
    >
      <motion.button
        whileHover={{ scale: 1.2 }}
        whileTap={{ scale: 0.9 }}
        className="relative flex items-center justify-center w-12 h-12 -ml-6 -mt-6 rounded-full bg-neutral-800 border border-white/10 shadow-lg text-white hover:border-white/30 transition-colors"
        style={{ color: isHovered ? planet.color : "#a3a3a3" }}
      >
        {planet.icon}

        {/* Tooltip */}
        <AnimatePresence>
          {isHovered && (
            <motion.div
              initial={{ opacity: 0, y: 10, scale: 0.8 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 5, scale: 0.9 }}
              className="absolute top-full mt-3 px-3 py-1 text-xs font-semibold text-white bg-neutral-900 border border-white/10 rounded-md whitespace-nowrap shadow-xl"
            >
              {planet.label}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.button>
    </motion.div>
  );
}

"use client";

import React, { useRef, useState, useEffect } from "react";
import { cn } from "@/lib/utils";

interface ScratchRevealProps {
  /** The content to reveal */
  children: React.ReactNode;
  /** Width of the scratch area */
  width?: number;
  /** Height of the scratch area */
  height?: number;
  /** How much area must be scratched to auto-reveal (0-1) */
  revealThreshold?: number;
  /** Radius of the scratch brush */
  brushSize?: number;
  className?: string;
}

export function PaperTearReveal({
  children,
  width = 300,
  height = 100,
  revealThreshold = 0.5,
  brushSize = 25,
  className,
}: ScratchRevealProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isRevealed, setIsRevealed] = useState(false);
  const [isScratching, setIsScratching] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) return;

    // Draw the gold foil cover
    const drawCover = () => {
      // Create a gradient to look like shiny gold foil
      const gradient = ctx.createLinearGradient(0, 0, width, height);
      gradient.addColorStop(0, "#d4af37"); // Gold
      gradient.addColorStop(0.3, "#f3e5ab"); // Light gold
      gradient.addColorStop(0.5, "#aa801e"); // Dark gold
      gradient.addColorStop(0.8, "#d4af37"); 
      gradient.addColorStop(1, "#f3e5ab");

      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, width, height);

      // Add a scratch pattern/texture
      ctx.fillStyle = "rgba(0,0,0,0.1)";
      for (let i = 0; i < 200; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const w = Math.random() * 20;
        const h = Math.random() * 2;
        ctx.fillRect(x, y, w, h);
      }

      // Add text on top
      ctx.fillStyle = "rgba(0,0,0,0.6)";
      ctx.font = "bold 16px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("SCRATCH TO REVEAL", width / 2, height / 2);
    };

    drawCover();
  }, [width, height]);

  const checkRevealThreshold = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const imageData = ctx.getImageData(0, 0, width, height);
    const pixels = imageData.data;

    let transparentPixels = 0;
    // Iterate over alpha values (every 4th byte)
    for (let i = 3; i < pixels.length; i += 4) {
      if (pixels[i] < 128) {
        transparentPixels++;
      }
    }

    const totalPixels = width * height;
    if (transparentPixels / totalPixels > revealThreshold) {
      setIsRevealed(true);
      // Clear the rest
      ctx.clearRect(0, 0, width, height);
    }
  };

  const handleScratch = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (isRevealed || !isScratching) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Use "destination-out" to erase the canvas
    ctx.globalCompositeOperation = "destination-out";
    ctx.beginPath();
    ctx.arc(x, y, brushSize, 0, Math.PI * 2);
    ctx.fill();

    // Reset composite operation so we don't accidentally erase other things
    ctx.globalCompositeOperation = "source-over";

    // Throttle the pixel array check (it's expensive)
    if (Math.random() < 0.1) {
      checkRevealThreshold();
    }
  };

  return (
    <div 
      className={cn("relative rounded-xl overflow-hidden shadow-2xl inline-block", className)}
      style={{ width, height }}
    >
      {/* Underlying Content */}
      <div className="absolute inset-0 flex items-center justify-center bg-neutral-900 border border-white/20 select-none">
        {children}
      </div>

      {/* Scratchable Canvas Layer */}
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        className={cn(
          "absolute inset-0 z-10 touch-none cursor-pointer transition-opacity duration-700",
          isRevealed ? "opacity-0 pointer-events-none" : "opacity-100"
        )}
        onPointerDown={(e) => {
          setIsScratching(true);
          e.currentTarget.setPointerCapture(e.pointerId);
          handleScratch(e); // allow tap-to-scratch
        }}
        onPointerMove={handleScratch}
        onPointerUp={(e) => {
          setIsScratching(false);
          e.currentTarget.releasePointerCapture(e.pointerId);
          checkRevealThreshold();
        }}
        onPointerLeave={() => setIsScratching(false)}
      />
    </div>
  );
}

