export function ThreeDBookFlip({ className }: { className?: string }) {
  const [currentPage, setCurrentPage] = useState(0);

  const nextPage = () => {
    if (currentPage < DEMO_PAGES.length - 1) {
      setCurrentPage((c) => c + 1);
    }
  };

  const prevPage = () => {
    if (currentPage > 0) {
      setCurrentPage((c) => c - 1);
    }
  };

  return (
    <div className={cn("relative w-full h-[500px] flex items-center justify-center perspective-[1500px] bg-neutral-950 rounded-xl overflow-hidden", className)}>

      {/* Table/Background gradient */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,rgba(255,255,255,0.05)_0%,transparent_70%)] pointer-events-none" />

      {/* Book Container */}
      <div className="relative w-[300px] h-[420px] transform-style-3d transition-transform duration-500">

        {/* Back cover (always stays at the very bottom right, representing the end of the book) */}
        <div className="absolute inset-0 bg-indigo-950 rounded-r-xl shadow-[20px_20px_40px_rgba(0,0,0,0.8)] border border-indigo-900/50" />

        {/* Pages */}
        {DEMO_PAGES.map((page, index) => {
          // A page is "turned" if its index is strictly less than the currentPage.
          // The current page is visible on the right.
          // Turned pages are visible on the left.
          const isTurned = index < currentPage;
          const isCurrent = index === currentPage;
          const zIndex = DEMO_PAGES.length - index;

          return (
            <motion.div
              key={page.id}
              className="absolute inset-0 origin-left transform-style-3d"
              style={{ zIndex: isTurned ? index : zIndex }}
              initial={false}
              animate={{
                rotateY: isTurned ? -180 : 0,
                // Add a tiny bit of z-translation to prevent z-fighting when stacked
                z: isTurned ? index : -index,
              }}
              transition={{
                type: "spring",
                stiffness: 40,
                damping: 12,
                mass: 0.8
              }}
            >
              {/* Front of Page (Right side when not turned) */}
              <div 
                className={cn(
                  "absolute inset-0 overflow-hidden rounded-r-xl border-y border-r border-black/10 bg-white",
                  isCurrent ? "shadow-[inset_20px_0_40px_rgba(0,0,0,0.1)]" : ""
                )}
                style={{ backfaceVisibility: "hidden" }}
              >
                {page.front}
                {/* Book spine shading */}
                <div className="absolute left-0 top-0 bottom-0 w-8 bg-gradient-to-r from-black/20 to-transparent mix-blend-multiply pointer-events-none" />
              </div>

              {/* Back of Page (Left side when turned) */}
              <div 
                className="absolute inset-0 overflow-hidden rounded-l-xl border-y border-l border-black/10 bg-white"
                style={{ transform: "rotateY(180deg)", backfaceVisibility: "hidden" }}
              >
                {page.back}
                {/* Book spine shading (reversed) */}
                <div className="absolute right-0 top-0 bottom-0 w-8 bg-gradient-to-l from-black/20 to-transparent mix-blend-multiply pointer-events-none" />
              </div>
            </motion.div>
          );
        })}

        {/* Center Spine Crease */}
        <div className="absolute left-0 top-0 bottom-0 w-[2px] bg-black/40 shadow-[0_0_10px_rgba(0,0,0,0.5)] z-50 transform -translate-x-1/2" />
      </div>

      {/* Controls */}
      <div className="absolute bottom-6 flex gap-4 z-50">
        <button
          onClick={prevPage}
          disabled={currentPage === 0}
          className="p-3 rounded-full bg-white/10 hover:bg-white/20 text-white disabled:opacity-30 transition-colors backdrop-blur-md border border-white/10"
        >
          <ChevronLeft size={24} />
        </button>
        <button
          onClick={nextPage}
          disabled={currentPage === DEMO_PAGES.length}
          className="p-3 rounded-full bg-white/10 hover:bg-white/20 text-white disabled:opacity-30 transition-colors backdrop-blur-md border border-white/10"
        >
          <ChevronRight size={24} />
        </button>
      </div>
    </div>
  );
}

"use client";

import React, { useRef } from "react";
import { motion, useScroll, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";

interface InfiniteFractalZoomProps {
  className?: string;
}

export function InfiniteFractalZoom({ className }: InfiniteFractalZoomProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  // We track the scroll progress of this highly tall container
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"]
  });

  return (
    <div 
      ref={containerRef} 
      className={cn("relative w-full h-[300vh] bg-neutral-950", className)}
    >
      <div className="sticky top-0 w-full h-screen overflow-hidden flex items-center justify-center perspective-[1000px]">
        {/* We generate multiple layers that will zoom past the camera */}
        {[...Array(6)].map((_, i) => (
          <ZoomLayer 
            key={i} 
            index={i} 
            totalLayers={6} 
            progress={scrollYProgress} 
          />
        ))}

        <div className="absolute bottom-10 left-0 right-0 text-center text-white/30 text-sm font-mono uppercase tracking-[0.3em] pointer-events-none">
          Scroll to Zoom
        </div>
      </div>
    </div>
  );
}

function ZoomLayer({ index, totalLayers, progress }: { index: number, totalLayers: number, progress: any }) {
  // Each layer starts at a different initial scale.
  // Layer 0 is the smallest (furthest back). Layer N is the largest (closest).

  // As scroll progress goes 0 -> 1, every layer grows exponentially.

  // Create an offset mapping so layers continually loop or expand outward.
  // Actually, for a single scrollytelling section, we just expand them massively.

  const initialScale = Math.pow(2.5, index - 2); // e.g. 0.16, 0.4, 1, 2.5, 6.25...

  // We use useTransform to multiply the initial scale by an exponential growth factor based on scroll
  const scale = useTransform(progress, [0, 1], [initialScale, initialScale * Math.pow(2.5, totalLayers)]);

  // Fade out as it gets too close to the camera (scale > 15)
  // Fade in as it approaches from the distance (scale < 0.2)
  const opacity = useTransform(scale, [0.1, 0.5, 5, 15], [0, 1, 1, 0]);

  // Rotate slightly as we zoom
  const rotateZ = useTransform(progress, [0, 1], [index * 15, index * 15 + 90]);

  // Color cycles
  const hue = (index * 60) % 360;

  return (
    <motion.div
      className="absolute flex items-center justify-center border-[2px] rounded-2xl shadow-[0_0_50px_rgba(0,0,0,0.5)_inset,0_0_50px_rgba(0,0,0,0.5)]"
      style={{
        width: "300px",
        height: "300px",
        scale,
        opacity,
        rotateZ,
        borderColor: `hsla(${hue}, 80%, 60%, 0.5)`,
        backgroundColor: `hsla(${hue}, 80%, 10%, 0.1)`,
      }}
    >
      <div 
        className="absolute inset-4 border border-dashed rounded-xl opacity-30" 
        style={{ borderColor: `hsla(${hue}, 80%, 70%, 1)` }} 
      />
    </motion.div>
  );
}
